                }
                case (byte)'M': sb.Append(t->tm_min.ToString("D2", ci)); break;
                case (byte)'S': sb.Append(t->tm_sec.ToString("D2", ci)); break;
                case (byte)'Z': sb.Append(CalendarZoneName(t)); break;
                case (byte)'z':
