                        // and avoid negating long.MinValue.
                        ulong magnitude = offset < 0 ? (ulong)(-(offset + 1)) + 1 : (ulong)offset;
                        sb.Append(offset < 0 ? '-' : '+');
                        sb.Append((magnitude / 3600).ToString("D2", ci));
                        sb.Append((magnitude / 60 % 60).ToString("D2", ci));
