                case (byte)'R': sb.Append($"{t->tm_hour:D2}:{t->tm_min:D2}"); break;
                case (byte)'D':
                    sb.Append($"{t->tm_mon + 1:D2}/{t->tm_mday:D2}/{(1900 + t->tm_year) % 100:D2}"); break;
