            "alpha" => upper || lower,
            "blank" => value == ' ' || value == '\t',
            "cntrl" => value < 32 || value == 127,
            "digit" => digit,
            "graph" => value >= 33 && value <= 126,
            "lower" => lower,
            "print" => value >= 32 && value <= 126,
            "punct" => value >= 33 && value <= 126 && !(upper || lower || digit),
            "space" => value == ' ' || (value >= 9 && value <= 13),
            "upper" => upper,
            "xdigit" => digit || (value >= 'a' && value <= 'f') || (value >= 'A' && value <= 'F'),
            _ => false
