                PosixWideClass.Punct => ispunct(c), PosixWideClass.Space => isspace(c),
                PosixWideClass.Upper => isupper(c), PosixWideClass.Xdigit => isxdigit(c), _ => 0
            };
        if ((uint)c > 0x10ffff || c is >= 0xd800 and <= 0xdfff) return 0;
        var service = posixUnicodeService.Value;
        if (service == null) { errno = ENOTSUP; return 0; }
        return PosixNativeIswctype((uint)c, service.Classes[(int)kind], service.Locale) != 0 ? 1 : 0;
    }

    public static int iswalnum(int c) => ClassifyBackendWide(c, PosixWideClass.Alnum);
    public static int iswalpha(int c) => ClassifyBackendWide(c, PosixWideClass.Alpha);
    public static int iswblank(int c) => ClassifyBackendWide(c, PosixWideClass.Blank);
    public static int iswcntrl(int c) => ClassifyBackendWide(c, PosixWideClass.Control);
    public static int iswdigit(int c) => ClassifyBackendWide(c, PosixWideClass.Digit);
    public static int iswgraph(int c) => ClassifyBackendWide(c, PosixWideClass.Graph);
    public static int iswlower(int c) => ClassifyBackendWide(c, PosixWideClass.Lower);
    public static int iswprint(int c) => ClassifyBackendWide(c, PosixWideClass.Print);
    public static int iswpunct(int c) => ClassifyBackendWide(c, PosixWideClass.Punct);
    public static int iswspace(int c) => ClassifyBackendWide(c, PosixWideClass.Space);
    public static int iswupper(int c) => ClassifyBackendWide(c, PosixWideClass.Upper);
    public static int iswxdigit(int c) => ClassifyBackendWide(c, PosixWideClass.Xdigit);

    public static int towlower(int c) => !EffectivePosixUtf8Locale || c < 128 ? tolower(c) : MapPosixWide(c, false);
    public static int towupper(int c) => !EffectivePosixUtf8Locale || c < 128 ? toupper(c) : MapPosixWide(c, true);

    private static readonly Lazy<nint> backendNumericLocale = new(() =>
    {
        if (!OperatingSystem.IsLinux()) return 0;
        try { fixed (byte* name = "C\0"u8) return PosixNativeNewlocale(2, name, 0); }
        catch (EntryPointNotFoundException) { return 0; }
        catch (DllNotFoundException) { return 0; }
    });

    /// <summary>Correctly rounded binary32 parsing in the runtime's C numeric
    /// locale, retaining native range, signed-zero, hex and end-pointer rules.
    /// A binary64 parse followed by a cast would introduce double rounding.</summary>
    public static float strtof(byte* text, byte** end)
    {
        if (text == null) { if (end != null) *end = null; errno = EFAULT; return 0; }
        nint locale = backendNumericLocale.Value;
        if (locale == 0) { if (end != null) *end = text; errno = ENOTSUP; return float.NaN; }
        try
        {
            float value = BackendNativeStrtof(text, end, locale);
            int error = Marshal.GetLastPInvokeError();
            if (error != 0) errno = error;
            return value;
        }
        catch (EntryPointNotFoundException) { if (end != null) *end = text; errno = ENOSYS; return float.NaN; }
        catch (DllNotFoundException) { if (end != null) *end = text; errno = ENOSYS; return float.NaN; }
    }

    [DllImport("libc", EntryPoint = "strtof_l", SetLastError = true)]
    private static extern float BackendNativeStrtof(byte* text, byte** end, nint locale);
}


#nullable restore
// ---- PosixClockLib.cs ----
#nullable enable


public static unsafe partial class Libc
{
    /// <summary>Resolution of the actual BCL source used by clock_gettime.
    /// NULL still validates the clock ID. No OS clock with a different source
    /// or resolution is substituted for the managed reading.</summary>
    public static int clock_getres(int clockId, timespec* resolution)
    {
        if (clockId != CLOCK_REALTIME && clockId != CLOCK_MONOTONIC) { errno = EINVAL; return -1; }
        if (resolution != null)
        {
            long nanos = clockId == CLOCK_REALTIME ? 100
                : (long)(((global::System.Int128)1_000_000_000 + global::System.Diagnostics.Stopwatch.Frequency - 1)
                    / global::System.Diagnostics.Stopwatch.Frequency);
            resolution->tv_sec = nanos / 1_000_000_000;
            resolution->tv_nsec = nanos % 1_000_000_000;
        }
        return 0;
    }

    public const int CLOCK_REALTIME = 0;
    public const int CLOCK_MONOTONIC = 1;

    /// <summary>POSIX wall and monotonic clocks. Clock readings have no mutable
    /// program state; errors use the calling owner's thread-local errno.</summary>
    public static int clock_gettime(int clockId, timespec* value)
    {
        if (clockId != CLOCK_REALTIME && clockId != CLOCK_MONOTONIC) { errno = EINVAL; return -1; }
        if (value == null) { errno = EFAULT; return -1; }
        if (clockId == CLOCK_REALTIME)
        {
            var now = global::System.DateTimeOffset.UtcNow;
            value->tv_sec = now.ToUnixTimeSeconds();
            value->tv_nsec = now.UtcTicks % global::System.TimeSpan.TicksPerSecond * 100;
        }
        else
        {
            long ticks = global::System.Diagnostics.Stopwatch.GetTimestamp();
            long frequency = global::System.Diagnostics.Stopwatch.Frequency;
            value->tv_sec = ticks / frequency;
            value->tv_nsec = (long)((global::System.Int128)(ticks % frequency) * 1_000_000_000 / frequency);
        }
        return 0;
    }

    /// <summary>Sleep for at least the requested interval, measured by the
    /// monotonic clock. Managed Thread.Interrupt maps to EINTR and reports the
    /// unslept interval; this does not install or emulate POSIX signal delivery.</summary>
    public static int nanosleep(timespec* request, timespec* remaining)
    {
        if (request == null) { errno = EFAULT; return -1; }
        long seconds = request->tv_sec, nanoseconds = request->tv_nsec;
        if (seconds < 0 || nanoseconds < 0 || nanoseconds >= 1_000_000_000) { errno = EINVAL; return -1; }
        // Int128 retains the full valid time_t range without overflowing when
        // converting seconds to nanoseconds or rounding the sleep chunk up.
        global::System.Int128 duration = (global::System.Int128)seconds * 1_000_000_000 + nanoseconds;
        long started = global::System.Diagnostics.Stopwatch.GetTimestamp();
        try
        {
            while (true)
            {
                var left = duration - PosixSleepElapsedNanoseconds(started);
                if (left <= 0) return 0;
                var milliseconds = (left + 999_999) / 1_000_000;
                global::System.Threading.Thread.Sleep(milliseconds > int.MaxValue ? int.MaxValue : (int)milliseconds);
            }
        }
        catch (global::System.Threading.ThreadInterruptedException)
        {
            if (remaining != null)
            {
                var left = duration - PosixSleepElapsedNanoseconds(started);
                if (left < 0) left = 0;
                remaining->tv_sec = (long)(left / 1_000_000_000);
                remaining->tv_nsec = (long)(left % 1_000_000_000);
            }
            errno = EINTR;
            return -1;
        }
    }

    private static global::System.Int128 PosixSleepElapsedNanoseconds(long started)
        => (global::System.Int128)(global::System.Diagnostics.Stopwatch.GetTimestamp() - started)
            * 1_000_000_000 / global::System.Diagnostics.Stopwatch.Frequency;
}


#nullable restore
// ---- PosixFsLib.cs ----
#nullable enable



/// <summary>
/// The POSIX filesystem surface beyond <c>&lt;stdio.h&gt;</c> streams:
/// <c>&lt;dirent.h&gt;</c> directory iteration, <c>open</c>, and the
/// <c>&lt;unistd.h&gt;</c>/<c>&lt;sys/stat.h&gt;</c> path operations
/// (<c>mkdir</c>/<c>rmdir</c>/<c>unlink</c>/<c>chdir</c>/<c>getcwd</c>/…). Present
/// so portable Unix C (chibi-scheme's <c>(chibi filesystem)</c>) compiles AND
/// behaves over <see cref="System.IO"/>.
/// </summary>
/// <remarks>
/// Mappings are faithful where .NET has the primitive (directory enumeration,
/// create/delete, cwd, symlinks). Where .NET has no managed API but the OS does,
/// the call forwards to the real primitive behind an <see cref="OperatingSystem"/>
/// switch — <c>link</c> (hard links) routes to <c>link(2)</c> on POSIX and
/// <c>CreateHardLinkW</c> on Windows. These P/Invokes are blittable
/// (pointers + <c>int</c>), so <c>[DllImport]</c> emits a direct AOT-clean call
/// with no marshalling stub, and — unlike <c>[LibraryImport]</c> — needs no
/// source generator, so it survives the runtime-block splice into the functional
/// tests' generator-less Roslyn compilation. Linux x64 advisory locks use the
/// real OS descriptor through the shared file-lock services. <c>chmod</c>
/// is best-effort (Unix mode bits via
/// <see cref="File.SetUnixFileMode(string, UnixFileMode)"/> where the host
/// supports it, else a no-op success).
/// </remarks>
public static unsafe partial class Libc
{
    // ---- <dirent.h> --------------------------------------------------------

    /// <summary>Per-open-directory state behind a <c>DIR*</c> token. The token
    /// is a tiny native allocation whose address keys this table; the dirent
    /// buffer is reused across <c>readdir</c> calls (C's "may be overwritten by
    /// the next call" contract).</summary>
    private sealed class DirState
    {
        public required string[] Names;
        public int Pos;
        public byte* Dirent;
    }

    private static Dictionary<nint, DirState> _dirs => OwnedPaths.Directories;
    private static Lock _dirsLock => OwnedPaths.Sync;

    // struct dirent (see include/dirent.h): d_name is FIRST, offset 0, 256 bytes.
    private const int DName = 256;

    /// <summary><c>opendir(name)</c> — snapshot the directory's entries (".",
    /// ".." then the real names, like POSIX) and return a <c>DIR*</c> token, or
    /// <c>null</c> (ENOENT/ENOTDIR) if it can't be read.</summary>
    public static void* opendir(byte* name)
    {
        if (name == null) { errno = ENOENT; return null; }
        var path = ResolvePath(name);
        string[] names;
        try
        {
            if (OperatingSystem.IsLinux() && RuntimeInformation.ProcessArchitecture == Architecture.X64)
            {
                // Exists suppresses kernel traversal errors. Enumerate one
                // actual opened directory, retaining its identity after rename.
                var snapshot = ReadLinuxDirectory(path);
                if (snapshot == null) return null;
                names = snapshot;
            }
            else
            {
                var entries = Directory.GetFileSystemEntries(path);
                names = new string[entries.Length + 2];
                names[0] = ".";
                names[1] = "..";
                for (var i = 0; i < entries.Length; i++) { names[i + 2] = global::System.IO.Path.GetFileName(entries[i]); }
            }
        }
        catch (UnauthorizedAccessException) { errno = EACCES; return null; }
        catch (DirectoryNotFoundException) { errno = ENOENT; return null; }
        catch (FileNotFoundException) { errno = ENOENT; return null; }
        catch (ArgumentException) { errno = EINVAL; return null; }
        catch (IOException) { errno = EIO; return null; }
        catch (OutOfMemoryException) { errno = ENOMEM; return null; }
        byte* token = null;
        byte* buf = null;
        try
        {
            token = (byte*)NativeMemory.Alloc(8);
            buf = (byte*)NativeMemory.Alloc((nuint)DName + 16);
            lock (_dirsLock) { _dirs.Add((nint)token, new DirState { Names = names, Dirent = buf }); }
            var result = token;
            token = buf = null; // ownership transfers only after registration
            return result;
        }
        catch (OutOfMemoryException) { errno = ENOMEM; return null; }
        finally { NativeMemory.Free(buf); NativeMemory.Free(token); }
    }

    [DllImport("libc", EntryPoint = "opendir", SetLastError = true)]
    private static extern nint HostOpenDirectory(byte* path);
    [DllImport("libc", EntryPoint = "readdir", SetLastError = true)]
    private static extern byte* HostReadDirectory(nint directory);
    [DllImport("libc", EntryPoint = "closedir", SetLastError = true)]
    private static extern int HostCloseDirectory(nint directory);

    private static string[]? ReadLinuxDirectory(string path)
    {
        nint directory;
        fixed (byte* bytes = Encoding.UTF8.GetBytes(path + "\0"))
            directory = HostOpenDirectory(bytes);
        if (directory == 0) { errno = Marshal.GetLastPInvokeError(); return null; }
        try
        {
            var names = new List<string>();
            while (true)
            {
                // .NET clears native errno before a SetLastError call, so
                // a null result distinguishes clean EOF from a read failure.
                byte* entry = HostReadDirectory(directory);
                if (entry == null)
                {
                    int error = Marshal.GetLastPInvokeError();
                    if (error != 0) { errno = error; return null; }
                    break;
                }
                // Linux x64 dirent: ino64/off64/reclen16/type8/name[]. This is
                // the host layout, independent of dotcc's public dirent ABI.
                names.Add(Marshal.PtrToStringUTF8((nint)(entry + 19))!);
            }
            return names.ToArray();
        }
        finally { HostCloseDirectory(directory); }
    }

    /// <summary><c>readdir(dirp)</c> — fill and return the reused
    /// <c>struct dirent</c> for the next entry (its <c>d_name</c> at offset 0),
    /// or <c>null</c> at end-of-directory / for an unknown token.</summary>
    public static void* readdir(void* dirp)
    {
        DirState? st;
        lock (_dirsLock) { _dirs.TryGetValue((nint)dirp, out st); }
        if (st == null) { errno = EBADF; return null; }
        if (st.Pos >= st.Names.Length) { return null; }
        var nm = st.Names[st.Pos++];
        new Span<byte>(st.Dirent, DName).Clear();
        var n = Encoding.UTF8.GetBytes(nm, new Span<byte>(st.Dirent, DName - 1));
        st.Dirent[n] = 0;
        return st.Dirent;
    }

    /// <summary><c>closedir(dirp)</c> — release the token, its dirent buffer and
    /// state. Returns 0, or -1 (EBADF) for an unknown token.</summary>
    public static int closedir(void* dirp)
    {
        DirState? st;
        lock (_dirsLock)
        {
            if (!_dirs.Remove((nint)dirp, out st)) { errno = EBADF; return -1; }
        }
        NativeMemory.Free(st!.Dirent);
        NativeMemory.Free(dirp);
        return 0;
    }

    /// <summary><c>rewinddir(dirp)</c> — restart iteration from the first entry
    /// of the snapshot taken at <c>opendir</c>.</summary>
    public static void rewinddir(void* dirp)
    {
        lock (_dirsLock) { if (_dirs.TryGetValue((nint)dirp, out var st)) { st.Pos = 0; } }
    }

    // ---- <fcntl.h> open ----------------------------------------------------

    /// <summary><c>open(path, flags)</c> — see the 3-arg overload; the mode is
    /// only consulted when O_CREAT actually creates the file.</summary>
    public static int open(byte* path, int flags) => open(path, flags, 0);

    /// <summary><c>open</c> as chibi emits it — <c>flags</c>/<c>mode</c> arrive at
    /// the width its <c>sexp_sint_value</c> produced (<c>long</c>). open is
    /// variadic in C; this is the concrete arity dotcc resolves against.</summary>
    public static int open(byte* path, long flags, long mode) => open(path, (int)flags, (int)mode);

    /// <summary><c>open(path, flags, mode)</c> — open/create a file and return a
    /// dotcc fd (a FileSlot index, same space as <c>fileno</c>), or -1. The O_*
    /// access/creation flags (see &lt;fcntl.h&gt;) map to .NET FileMode/Access;
    /// O_CREAT applies <paramref name="mode"/> best-effort via chmod.</summary>
    public static int open(byte* path, int flags, int mode)
    {
        if (path == null) { errno = ENOENT; return -1; }
        var p = ResolvePath(path);
        if ((flags & 0x20000) != 0) return OpenLinuxFile(p, flags, mode);
        // A path-based FileStream silently takes an flock share lock. POSIX
        // open must not acquire an application advisory lock, or fail merely
        // because another process holds one. Reuse the existing native-open
        // owning-handle path on its supported ABI, also when O_NOFOLLOW is off.
        if (OperatingSystem.IsLinux() && RuntimeInformation.ProcessArchitecture == Architecture.X64)
            return OpenLinuxFile(p, flags, mode);
        if (Directory.Exists(p)) { errno = EISDIR; return -1; }
        const int oCreat = 0x40, oExcl = 0x80, oTrunc = 0x200, oAppend = 0x400;
        var access = (flags & 0x3) switch
        {
            0x1 => FileAccess.Write,
            0x2 => FileAccess.ReadWrite,
            _ => FileAccess.Read,
        };
        FileMode fmode;
        if ((flags & oCreat) != 0 && (flags & oExcl) != 0) { fmode = FileMode.CreateNew; }
        else if ((flags & oCreat) != 0 && (flags & oTrunc) != 0) { fmode = FileMode.Create; }
        else if ((flags & oTrunc) != 0) { fmode = FileMode.Truncate; }
        else if ((flags & oCreat) != 0) { fmode = FileMode.OpenOrCreate; }
        else { fmode = FileMode.Open; }
        try
        {
            var stream = new FileStream(p, fmode, access, FileShare.ReadWrite | FileShare.Delete);
            var fd = RegisterFileSlot(stream);
            var slot = SlotByFd(fd)!;
            slot.StatusFlags = (flags & (3 | oAppend | 0x800));
            slot.DescriptorFlags = (flags & 0x80000) != 0 ? 1 : 0;
            if ((flags & oCreat) != 0 && mode != 0) { TrySetUnixMode(p, mode); }
            return fd;
        }
        catch (FileNotFoundException) { errno = ENOENT; return -1; }
        catch (DirectoryNotFoundException) { errno = ENOENT; return -1; }
        catch (IOException) when ((flags & oExcl) != 0 && File.Exists(p)) { errno = EEXIST; return -1; }
        catch (UnauthorizedAccessException) { errno = EACCES; return -1; }
        catch (ArgumentException) { errno = EINVAL; return -1; }
        catch (IOException) { errno = EIO; return -1; }
    }

    // Native open(2) supplies atomic O_NOFOLLOW and creates no hidden flock.
    // The FileStream adopts this original owning SafeFileHandle without a
    // second path open, advisory sharing lock, duplicate or premature close.
    private static int OpenLinuxFile(string path, int flags, int mode)
    {
        if (!OperatingSystem.IsLinux() || RuntimeInformation.ProcessArchitecture != Architecture.X64)
        { errno = ENOTSUP; return -1; }
        var stream = OpenLinuxStream(path, flags, mode);
        if (stream is null) return -1;
        try
        {
            int fd = RegisterFileSlot(stream);
            var slot = SlotByFd(fd)!;
            slot.StatusFlags = flags & (3 | 0x400 | 0x800);
            slot.DescriptorFlags = (flags & 0x80000) != 0 ? 1 : 0;
            return fd;
        }
        catch (OutOfMemoryException) { stream.Dispose(); errno = ENOMEM; return -1; }
    }

    // Shared by POSIX open, stdio opens and exclusive temporary creation.
    // SafeFileHandle owns the original descriptor; FileStream never reopens the
    // path or acquires a .NET sharing flock. No synthetic fd reaches the OS.
    private static Stream? OpenLinuxStream(string path, int flags, int mode)
    {
        int descriptor = OpenLinuxCreatedDescriptor(path, flags, (uint)mode);
        if (descriptor < 0) return null;
        return AdoptBackendLinuxStream(descriptor, flags);
    }

    [DllImport("libc", EntryPoint = "open", SetLastError = true)]
    private static extern int PosixOpenFile(byte* path, int flags, int mode);

    // ---- path operations (<unistd.h> / <sys/stat.h> / <stdlib.h>) ----------

    /// <summary><c>mkdir(path, mode)</c> — create a directory; 0 on success, -1
    /// (EEXIST if it already exists, else EIO/EACCES). <paramref name="mode"/>
    /// is applied best-effort.</summary>
    public static int mkdir(byte* path, uint mode)
    {
        if (OperatingSystem.IsLinux() && RuntimeInformation.ProcessArchitecture == Architecture.X64)
            return BackendMkdir(path, mode);
        var p = ResolvePath(path);
        if (Directory.Exists(p) || File.Exists(p)) { errno = EEXIST; return -1; }
        try { Directory.CreateDirectory(p); TrySetUnixMode(p, (int)mode); return 0; }
        catch (UnauthorizedAccessException) { errno = EACCES; return -1; }
        catch (IOException) { errno = EIO; return -1; }
    }

    /// <summary><c>rmdir(path)</c> — remove an empty directory; 0 on success, -1
    /// (ENOENT/ENOTDIR/EIO; a non-empty directory yields EEXIST, the closest
    /// errno dotcc carries to ENOTEMPTY).</summary>
    public static int rmdir(byte* path)
    {
        var p = ResolvePath(path);
        if (!Directory.Exists(p)) { errno = File.Exists(p) ? ENOTDIR : ENOENT; return -1; }
        try { Directory.Delete(p, recursive: false); return 0; }
        catch (IOException) { errno = EEXIST; return -1; }   // not empty
        catch (UnauthorizedAccessException) { errno = EACCES; return -1; }
    }

    /// <summary><c>unlink(path)</c> — remove a file; 0 on success, -1
    /// (ENOENT/EACCES/EIO).</summary>
    public static int unlink(byte* path)
    {
        var p = ResolvePath(path);
        if (!File.Exists(p)) { errno = ENOENT; return -1; }
        try { File.Delete(p); return 0; }
        catch (UnauthorizedAccessException) { errno = EACCES; return -1; }
        catch (IOException) { errno = EIO; return -1; }
    }

    /// <summary><c>chdir(path)</c> — change the working directory; 0 on success,
    /// -1 (ENOENT/EACCES).</summary>
    public static int chdir(byte* path)
    {
        try
        {
            if (RuntimeContext.Current is { } owner)
            {
                lock (OwnedPaths.Sync)
                {
                    string p = ResolvePath(path);
                    if (p.Length == 0) { errno = ENOENT; return -1; }
                    string? physical = PhysicalDirectory(p);
                    if (physical is null) return -1;
                    owner.WorkingDirectory = physical;
                }
            }
            else
            {
                string p = Str(path);
                if (!Directory.Exists(p)) { errno = File.Exists(p) ? ENOTDIR : ENOENT; return -1; }
                Directory.SetCurrentDirectory(p);
            }
            return 0;
        }
        catch (UnauthorizedAccessException) { errno = EACCES; return -1; }
        catch (ArgumentException) { errno = EINVAL; return -1; }
        catch (IOException) { errno = EIO; return -1; }
    }

    /// <summary><c>getcwd(buf, size)</c> — copy the working directory into
    /// <paramref name="buf"/> (NUL-terminated) and return it, or <c>null</c>
    /// (ERANGE) if it doesn't fit. A <c>null</c> buf allocates size bytes, or
    /// enough for the path when size is zero (GNU extension); the caller frees
    /// it through this runtime's allocator.</summary>
    public static byte* getcwd(byte* buf, ulong size)
    {
        if (buf != null && size == 0) { errno = EINVAL; return null; }
        try
        {
            // A deleted process cwd makes GetCurrentDirectory throw. Contain
            // that failure at the C boundary, before allocating any output.
            string cwd = CurrentWorkingDirectory;
            if (RuntimeContext.Current is not null)
            {
                // Explicit owners have a path-based virtual cwd, not a host
                // directory descriptor. Do not report a vanished cached path
                // as success, or change the process cwd to inspect it.
                if ((File.GetAttributes(cwd) & FileAttributes.Directory) == 0)
                { errno = ENOTDIR; return null; }
            }
            int length = Encoding.UTF8.GetByteCount(cwd);
            ulong need = (ulong)length + 1;
            ulong capacity = buf == null && size == 0 ? need : size;
            if (need > capacity) { errno = ERANGE; return null; }
            if (buf == null)
            {
                if (capacity > (ulong)nuint.MaxValue) { errno = ENOMEM; return null; }
                buf = (byte*)AllocateHeap((nuint)capacity);
                if (buf == null) { errno = ENOMEM; return null; }
            }
            // The caller's size_t can exceed Int32.MaxValue. Only construct a
            // span over the bytes actually written, never over that capacity.
            Encoding.UTF8.GetBytes(cwd, new Span<byte>(buf, length));
            buf[length] = 0;
            return buf;
        }
        catch (FileNotFoundException) { errno = ENOENT; return null; }
        catch (DirectoryNotFoundException) { errno = ENOENT; return null; }
        catch (UnauthorizedAccessException) { errno = EACCES; return null; }
        catch (PathTooLongException) { errno = ENAMETOOLONG; return null; }
        catch (IOException) { errno = EIO; return null; }
        catch (OutOfMemoryException) { errno = ENOMEM; return null; }
    }

    /// <summary><c>chmod(path, mode)</c> — set Unix permission bits best-effort
    /// (a no-op success where the host doesn't support them). Returns 0, or -1
    /// (ENOENT) if the path doesn't exist.</summary>
    public static int chmod(byte* path, uint mode)
    {
        var p = ResolvePath(path);
        if (!File.Exists(p) && !Directory.Exists(p)) { errno = ENOENT; return -1; }
        TrySetUnixMode(p, (int)mode);
        return 0;
    }

    /// <summary><c>symlink(target, linkpath)</c> — create a symbolic link; 0 on
    /// success, -1 with errno on failure. Linux x64 uses the native primitive
    /// to retain traversal errors, including ENOENT/ENOTDIR/EACCES/ELOOP.
    /// Only linkpath is owner-relative; target bytes are stored unchanged.</summary>
    public static int symlink(byte* target, byte* linkpath)
    {
        try
        {
            if (OperatingSystem.IsLinux() && RuntimeInformation.ProcessArchitecture == Architecture.X64)
            {
                byte[]? name = linkpath == null ? null : Encoding.UTF8.GetBytes(ResolvePath(linkpath) + "\0");
                fixed (byte* path = name)
                {
                    int result = PosixSymbolicLink(target, path);
                    if (result < 0) errno = Marshal.GetLastPInvokeError();
                    return result;
                }
            }
            if (target == null || linkpath == null) { errno = EFAULT; return -1; }
            var lnk = ResolvePath(linkpath);
            try { File.CreateSymbolicLink(lnk, Str(target)); return 0; }
            catch (IOException) when (File.Exists(lnk) || Directory.Exists(lnk)) { errno = EEXIST; return -1; }
        }
        catch (UnauthorizedAccessException) { errno = EACCES; return -1; }
        catch (FileNotFoundException) { errno = ENOENT; return -1; }
        catch (DirectoryNotFoundException) { errno = ENOENT; return -1; }
        catch (PathTooLongException) { errno = ENAMETOOLONG; return -1; }
        catch (ArgumentException) { errno = EINVAL; return -1; }
        catch (IOException) { errno = EIO; return -1; }
        catch (OutOfMemoryException) { errno = ENOMEM; return -1; }
    }

    /// <summary><c>readlink(path, buf, bufsiz)</c> — write the symlink target
    /// without a NUL terminator into <paramref name="buf"/>, truncated to
    /// <paramref name="bufsiz"/>; returns the byte count, or -1 with errno.
    /// Linux x64 retains native path errors and size_t behavior, including
    /// EINVAL for zero capacity or an existing nonlink. Only path is resolved
    /// against the caller's owner cwd; the stored target is never resolved.</summary>
    public static long readlink(byte* path, byte* buf, ulong bufsiz)
    {
        try
        {
            if (OperatingSystem.IsLinux() && RuntimeInformation.ProcessArchitecture == Architecture.X64)
            {
                byte[]? name = path == null ? null : Encoding.UTF8.GetBytes(ResolvePath(path) + "\0");
                fixed (byte* p = name)
                {
                    long result = PosixReadLink(p, buf, bufsiz);
                    if (result < 0) errno = Marshal.GetLastPInvokeError();
                    return result;
                }
            }
            if (bufsiz == 0) { errno = EINVAL; return -1; }
            if (path == null || buf == null) { errno = EFAULT; return -1; }
            var namePath = ResolvePath(path);
            string? target = (File.Exists(namePath) ? new FileInfo(namePath) : (FileSystemInfo)new DirectoryInfo(namePath)).LinkTarget;
            if (target == null) { errno = EINVAL; return -1; }
            var bytes = Encoding.UTF8.GetBytes(target);
            int n = (int)Math.Min((ulong)bytes.Length, bufsiz);
            new ReadOnlySpan<byte>(bytes, 0, n).CopyTo(new Span<byte>(buf, n));
            return n;
        }
        catch (UnauthorizedAccessException) { errno = EACCES; return -1; }
        catch (FileNotFoundException) { errno = ENOENT; return -1; }
        catch (DirectoryNotFoundException) { errno = ENOENT; return -1; }
        catch (PathTooLongException) { errno = ENAMETOOLONG; return -1; }
        catch (ArgumentException) { errno = EINVAL; return -1; }
        catch (IOException) { errno = EIO; return -1; }
        catch (OutOfMemoryException) { errno = ENOMEM; return -1; }
    }

    [DllImport("libc", EntryPoint = "symlink", SetLastError = true)]
    private static extern int PosixSymbolicLink(byte* target, byte* linkpath);
    [DllImport("libc", EntryPoint = "readlink", SetLastError = true)]
    private static extern long PosixReadLink(byte* path, byte* buf, ulong bufsiz);

    /// <summary><c>link(oldpath, newpath)</c> — create a hard link
    /// <paramref name="newpath"/> to the existing file <paramref name="oldpath"/>.
    /// .NET has no managed hard-link API, so this forwards to the real OS
    /// primitive: <c>link(2)</c> on POSIX, <c>CreateHardLinkW</c> on Windows.
    /// 0 on success, -1 with <c>errno</c> set (EEXIST/ENOENT/EACCES/EXDEV/…) on
    /// failure.</summary>
    public static int link(byte* oldpath, byte* newpath)
    {
        if (OperatingSystem.IsWindows())
        {
            // CreateHardLinkW(newLink, existingFile, NULL): note the argument
            // order is the reverse of POSIX link(oldpath=existing, newpath=new).
            // `fixed` on a managed string pins its (NUL-terminated) UTF-16
            // buffer, so the W API gets a `char*` with no string marshalling —
            // the signature stays blittable and AOT-clean.
            var existing = ResolvePath(oldpath);
            var newLink = ResolvePath(newpath);
            fixed (char* e = existing)
            fixed (char* n = newLink)
            {
                if (CreateHardLinkW(n, e, null) != 0) { return 0; }
            }
            errno = Win32ToErrno(Marshal.GetLastWin32Error());
            return -1;
        }
        // Native path operands must use the same owner cwd as managed file I/O.
        if (oldpath == null || newpath == null) { errno = EFAULT; return -1; }
        fixed (byte* oldName = Encoding.UTF8.GetBytes(ResolvePath(oldpath) + "\0"))
        fixed (byte* newName = Encoding.UTF8.GetBytes(ResolvePath(newpath) + "\0"))
            if (PosixLink(oldName, newName) == 0) { return 0; }
        errno = Marshal.GetLastPInvokeError();
        return -1;
    }

    [DllImport("libc", EntryPoint = "link", SetLastError = true)]
    private static extern int PosixLink(byte* oldpath, byte* newpath);

    [DllImport("kernel32.dll", EntryPoint = "CreateHardLinkW", SetLastError = true)]
    private static extern int CreateHardLinkW(char* lpFileName, char* lpExistingFileName, void* lpSecurityAttributes);

    /// <summary>Map the handful of Win32 error codes the filesystem primitives
    /// raise onto the matching POSIX <c>errno</c> value, so cross-platform C code
    /// comparing <c>errno</c> against EEXIST/ENOENT/… behaves the same on Windows
    /// as on Unix. Unmapped codes fall back to EPERM ("operation not
    /// permitted").</summary>
    private static int Win32ToErrno(int err) => err switch
    {
        2 or 3 => ENOENT,    // ERROR_FILE_NOT_FOUND / ERROR_PATH_NOT_FOUND
        5 => EACCES,         // ERROR_ACCESS_DENIED
        17 => EXDEV,         // ERROR_NOT_SAME_DEVICE
        80 or 183 => EEXIST, // ERROR_FILE_EXISTS / ERROR_ALREADY_EXISTS
        _ => EPERM,
    };

    /// <summary><c>realpath(path, resolved)</c> — canonicalize an EXISTING path;
    /// writes into <paramref name="resolved"/> (or allocates when it's
    /// <c>null</c>, the GNU/POSIX.1-2008 form) and returns it, or <c>null</c>
    /// (ENOENT) if the path doesn't exist.</summary>
    public static byte* realpath(byte* path, byte* resolved)
    {
        var p = ResolvePath(path);
        string full;
        try { full = global::System.IO.Path.GetFullPath(p); }
        catch (Exception) { errno = EINVAL; return null; }
        if (!File.Exists(full) && !Directory.Exists(full)) { errno = ENOENT; return null; }
        var need = Encoding.UTF8.GetByteCount(full) + 1;
        if (resolved == null) { resolved = (byte*)AllocateHeap((nuint)need); if (resolved == null) { errno = ENOMEM; return null; } }
        var n = Encoding.UTF8.GetBytes(full, new Span<byte>(resolved, need));
        resolved[n] = 0;
        return resolved;
    }

    // ---- <sys/file.h> ------------------------------------------------------

    // ---- more <unistd.h> ---------------------------------------------------

    /// <summary><c>access(path, mode)</c> — 0 when the path exists and the
    /// requested access is plausible (W_OK denied on a read-only file), else -1
    /// (ENOENT/EACCES). X_OK/R_OK can't be checked portably, so existence
    /// suffices for them.</summary>
    public static int access(byte* path, int mode)
    {
        var p = ResolvePath(path);
        var isFile = File.Exists(p);
        if (!isFile && !Directory.Exists(p)) { errno = ENOENT; return -1; }
        const int wOk = 2;
        if ((mode & wOk) != 0 && isFile)
        {
            try { if ((File.GetAttributes(p) & FileAttributes.ReadOnly) != 0) { errno = EACCES; return -1; } }
            catch (IOException) { errno = EIO; return -1; }
        }
        return 0;
    }

    /// <summary><c>chown(path, owner, group)</c> — change file ownership. POSIX
    /// <c>chown(2)</c> on Unix (faithful: a non-root caller can only chown to its
    /// own uid/gid, else EPERM — a real result, not a faked 0). Windows has no
    /// uid/gid model, so it's a no-op success on an existing path (-1 ENOENT if
    /// the path is missing, matching what POSIX would report first).</summary>
    public static int chown(byte* path, uint owner, uint group)
    {
        if (OperatingSystem.IsWindows())
        {
            var p = ResolvePath(path);
            if (!File.Exists(p) && !Directory.Exists(p)) { errno = ENOENT; return -1; }
            return 0;
        }
        if (path == null) { errno = EFAULT; return -1; }
        fixed (byte* name = Encoding.UTF8.GetBytes(ResolvePath(path) + "\0"))
            if (PosixChown(name, owner, group) == 0) { return 0; }
        errno = Marshal.GetLastPInvokeError();
        return -1;
    }

    [DllImport("libc", EntryPoint = "chown", SetLastError = true)]
    private static extern int PosixChown(byte* path, uint owner, uint group);

    /// <summary><c>ftruncate(fd, length)</c> — resize the fd's backing file to
    /// <paramref name="length"/> bytes without changing its offset, including
    /// offsets beyond EOF. Returns 0 on success, -1 with errno on failure.</summary>
    public static int ftruncate(int fd, long length)
    {
        if (length < 0) { errno = EINVAL; return -1; }
        var s = SlotByFd(fd);
        if (s is null) { errno = EBADF; return -1; }
        if (s.Stream is not { CanSeek: true, CanWrite: true } st) { errno = EINVAL; return -1; }
        try
        {
            if (st is FileStream file)
            {
                // Use the registered stream's owning handle, never the dotcc fd.
                // Exposing it first flushes BCL buffers. The positional resize
                // leaves both managed and OS offsets alone, without a seek/restore
                // race with other users of this open file. C stdio buffers remain
                // the caller's responsibility (fflush before descriptor access).
                if (!OperatingSystem.IsWindows())
                {
                    if (ResizeFile(file.SafeFileHandle, length) == 0) return 0;
                    errno = Marshal.GetLastPInvokeError();
                    return -1;
                }
                RandomAccess.SetLength(file.SafeFileHandle, length);
            }
            else
            {
                long position = st.Position;
                st.SetLength(length);
                if (st.Position != position) st.Position = position;
            }
            return 0;
        }
        catch (ObjectDisposedException) { errno = EBADF; return -1; }
        catch (ArgumentOutOfRangeException) { errno = EINVAL; return -1; }
        catch (UnauthorizedAccessException) { errno = EACCES; return -1; }
        catch (IOException) { errno = EIO; return -1; }

        [DllImport("libc", EntryPoint = "ftruncate", SetLastError = true)]
        static extern int ResizeFile(SafeFileHandle handle, long size);
    }

    /// <summary><c>mkfifo(path, mode)</c> — create a named pipe (FIFO). Forwards
    /// to <c>mkfifo(3)</c> on POSIX. Windows named pipes aren't filesystem
    /// objects (no <c>mkfifo</c> equivalent that a path-based open could reopen),
    /// so on Windows it stays an honest EPERM.</summary>
    public static int mkfifo(byte* path, uint mode)
    {
        if (OperatingSystem.IsWindows()) { errno = EPERM; return -1; }
        if (path == null) { errno = EFAULT; return -1; }
        fixed (byte* name = Encoding.UTF8.GetBytes(ResolvePath(path) + "\0"))
            if (PosixMkfifo(name, mode) == 0) { return 0; }
        errno = Marshal.GetLastPInvokeError();
        return -1;
    }

    [DllImport("libc", EntryPoint = "mkfifo", SetLastError = true)]
    private static extern int PosixMkfifo(byte* path, uint mode);

    /// <summary>Duplicate an owned file/console descriptor with a shared open
    /// file description and independent descriptor close lifetime.</summary>
    public static int dup(int fd) => DuplicateDescriptor(fd, null);

    /// <inheritdoc cref="dup(int)"/>
    public static int dup2(int oldfd, int newfd) => DuplicateDescriptor(oldfd, newfd);

    // ---- helpers -----------------------------------------------------------

    /// <summary>Decode a NUL-terminated UTF-8 C string to a managed string
    /// (empty for <c>null</c>).</summary>
    private static string Str(byte* s) => s == null ? string.Empty : Encoding.UTF8.GetString(s, strlen(s));

    /// <summary>Apply Unix permission bits where the host supports them; ignore
    /// failure (a path that vanished) — chmod is best-effort. On Windows there
    /// are no Unix mode bits, so it's a no-op: <see cref="File.SetUnixFileMode(string, UnixFileMode)"/>
    /// is unsupported there (the explicit OS guard both expresses that and
    /// satisfies CA1416, rather than catching the PlatformNotSupportedException).</summary>
    private static void TrySetUnixMode(string path, int mode)
    {
        if (OperatingSystem.IsWindows()) { return; }
        try { File.SetUnixFileMode(path, (UnixFileMode)(mode & 0xFFF)); }
        catch { /* a path that vanished mid-call — best-effort */ }
    }
}


#nullable restore
// ---- PosixHostLib.cs ----
#nullable enable


public static unsafe partial class Libc
{
    // These imports use the Linux x64 LP64 ABI declared by the guest headers.
    private static bool PosixHostAbi => OperatingSystem.IsLinux() &&
        RuntimeInformation.ProcessArchitecture == Architecture.X64 && IntPtr.Size == 8;

    private static bool SharedMemoryName(byte* name)
    {
        if (name == null) { errno = EFAULT; return false; }
        if (name[0] != (byte)'/' || name[1] == 0) { errno = EINVAL; return false; }
        int length = 1;
        for (; length <= 256 && name[length] != 0; length++)
            if (name[length] == (byte)'/') { errno = EINVAL; return false; }
        if (length > 256) { errno = ENAMETOOLONG; return false; }
        if (name[1] == (byte)'.' && (name[2] == 0 || (name[2] == (byte)'.' && name[3] == 0)))
        { errno = EINVAL; return false; }
        return true;
    }

    /// <summary>Real named POSIX shared memory. The OS descriptor transfers to
    /// an owning FileStream and then the current owner's descriptor table;
    /// callers receive only a guest descriptor, usable by the existing mmap.</summary>
    public static int shm_open(byte* name, int flags, uint mode)
    {
        if (!SharedMemoryName(name)) return -1;
        const int allowed = 2 | 0x40 | 0x80 | 0x200 | 0x80000;
        if ((flags & ~allowed) != 0) { errno = EINVAL; return -1; }
        if (!PosixHostAbi) { errno = ENOTSUP; return -1; }
        int descriptor = HostSharedMemoryOpen(name, flags, mode);
        if (descriptor < 0) { errno = Marshal.GetLastPInvokeError(); return -1; }
        var handle = new SafeFileHandle((IntPtr)descriptor, ownsHandle: true);
        FileStream? stream = null;
        try
        {
            stream = new FileStream(handle, (flags & 3) == 2 ? FileAccess.ReadWrite : FileAccess.Read, bufferSize: 1);
            int guest = RegisterFileSlot(stream);
            SlotByFd(guest)!.DescriptorFlags = 1; // shm_open always sets FD_CLOEXEC
            return guest;
        }
        catch (Exception error) when (error is IOException or ArgumentException or UnauthorizedAccessException or OutOfMemoryException)
        {
            if (stream != null) stream.Dispose(); else handle.Dispose();
            errno = error is OutOfMemoryException ? ENOMEM : error is UnauthorizedAccessException ? EACCES : EIO;
            return -1;
        }
    }

    /// <summary>Remove the shared name. Existing descriptors/mappings retain
    /// the unlinked object until their actual owning resources are released.</summary>
    public static int shm_unlink(byte* name)
    {
        if (!SharedMemoryName(name)) return -1;
        if (!PosixHostAbi) { errno = ENOTSUP; return -1; }
        int result = HostSharedMemoryUnlink(name);
        if (result < 0) errno = Marshal.GetLastPInvokeError();
        return result;
    }

    // void* deliberately accepts the struct emitted from the actual C header.
    // Linux libc reads/writes the 60-byte, 4-aligned guest termios unchanged.
    public static int tcgetattr(int descriptor, void* attributes) => TerminalAttributes(descriptor, 0, attributes, false);
    public static int tcsetattr(int descriptor, int action, void* attributes) => TerminalAttributes(descriptor, action, attributes, true);

    private static int TerminalAttributes(int descriptor, int action, void* attributes, bool setting)
    {
        var slot = SlotByFd(descriptor);
        if (slot == null) { errno = EBADF; return -1; }
        if (attributes == null) { errno = EFAULT; return -1; }
        if (!PosixHostAbi) { errno = ENOTSUP; return -1; }
        try
        {
            int result;
            if (slot.Kind == FileSlot.K.File && slot.Stream is FileStream file)
                result = setting ? HostSetTerminal(file.SafeFileHandle, action, attributes) : HostGetTerminal(file.SafeFileHandle, attributes);
            else
            {
                // fd 0/1/2 may have been freopen'd or replaced by an owned
                // pipe/file. Only genuine console kinds use OS std handles.
                int native = slot.Kind switch
                {
                    FileSlot.K.In when descriptor == 0 => 0,
                    FileSlot.K.Out when descriptor == 1 => 1,
                    FileSlot.K.Err when descriptor == 2 => 2,
                    _ => -1,
                };
                if (native < 0) { errno = ENOTTY; return -1; }
                result = setting ? HostSetStandardTerminal(native, action, attributes) : HostGetStandardTerminal(native, attributes);
            }
            if (result < 0) errno = Marshal.GetLastPInvokeError();
            return result;
        }
        catch (ObjectDisposedException) { errno = EBADF; return -1; }
    }

    [DllImport("libc", EntryPoint = "shm_open", SetLastError = true)]
    private static extern int HostSharedMemoryOpen(byte* name, int flags, uint mode);
    [DllImport("libc", EntryPoint = "shm_unlink", SetLastError = true)]
    private static extern int HostSharedMemoryUnlink(byte* name);
    [DllImport("libc", EntryPoint = "tcgetattr", SetLastError = true)]
    private static extern int HostGetTerminal(SafeFileHandle descriptor, void* attributes);
    [DllImport("libc", EntryPoint = "tcsetattr", SetLastError = true)]
    private static extern int HostSetTerminal(SafeFileHandle descriptor, int action, void* attributes);
    [DllImport("libc", EntryPoint = "tcgetattr", SetLastError = true)]
    private static extern int HostGetStandardTerminal(int descriptor, void* attributes);
    [DllImport("libc", EntryPoint = "tcsetattr", SetLastError = true)]
    private static extern int HostSetStandardTerminal(int descriptor, int action, void* attributes);
}


