            if (state.Owner != 0 && attempt) return EBUSY;
            if (state.Owner == me && state.Type == PTHREAD_MUTEX_ERRORCHECK) return EDEADLK;
            if (state.Owner != 0 && timed && !PthreadValidDeadline(deadline)) return EINVAL;
            state.Waiters++;
