        };
        SkipInputWs();
        int remaining = width < 0 ? int.MaxValue : width;
        bool negative = false, any = false;
        value = 0;
        int peek = _r.Peek();
        if (remaining > 0 && (peek == '-' || peek == '+'))
        {
            negative = peek == '-'; _r.Read(); remaining--;
        }
        if (remaining > 0 && _r.Peek() == '0')
        {
            any = true; _r.Read(); remaining--;
            if (radix == 0) radix = 8;
            if (remaining > 0 && (radix == 8 && spec == 'i' || radix == 16) && (_r.Peek() == 'x' || _r.Peek() == 'X'))
            {
                _r.Read(); remaining--; radix = 16;
            }
        }
        if (radix == 0) radix = 10;
        while (remaining > 0 && (peek = _r.Peek()) != -1)
        {
            int digit = DigitValue(peek, radix);
            if (digit < 0) break;
            value = unchecked(value * (uint)radix + (uint)digit);
            any = true; _r.Read(); remaining--;
        }
        if (negative) value = unchecked(0UL - value);
        return any;
    }

    public ScanfReader Read(double* dst)
    {
        if (_failed) return this;
        var spec = ExpectSpec(out int width);
        if (_failed) return this;
        if (spec != (byte)'f' && spec != (byte)'e' && spec != (byte)'g'
            && spec != (byte)'F' && spec != (byte)'E' && spec != (byte)'G')
        {
            throw Unsupported(spec, "a double (%f %e %g)");
        }
        SkipInputWs();
        int consumed = 0;
        var sb = new StringBuilder();
        int peek = _r.Peek();
        if ((peek == '-' || peek == '+') && (width < 0 || consumed < width))
        {
            sb.Append((char)_r.Read());
            consumed++;
        }
        bool sawDigit = false;
        bool sawDot = false;
        bool sawExp = false;
        while ((width < 0 || consumed < width) && (peek = _r.Peek()) != -1)
        {
            if (peek >= '0' && peek <= '9') { sawDigit = true; sb.Append((char)_r.Read()); consumed++; }
            else if (peek == '.' && !sawDot && !sawExp) { sawDot = true; sb.Append((char)_r.Read()); consumed++; }
            else if ((peek == 'e' || peek == 'E') && sawDigit && !sawExp && (width < 0 || consumed < width))
            {
                sawExp = true;
                sb.Append((char)_r.Read());
                consumed++;
                int p2 = _r.Peek();
                if ((p2 == '-' || p2 == '+') && (width < 0 || consumed < width)) { sb.Append((char)_r.Read()); consumed++; }
            }
            else { break; }
        }
        if (sawDigit && double.TryParse(sb.ToString(), NumberStyles.Float, CultureInfo.InvariantCulture, out double v))
        {
            *dst = v;
            _matched++;
        }
        else _failed = true;
        return this;
    }

    public ScanfReader Read(byte* dst)
    {
        if (_failed) return this;
        var spec = ExpectSpec(out int width);
        if (_failed) return this;
        if (spec != (byte)'s' && spec != (byte)'c')
        {
            if (ReadIntegerValue(spec, width, out ulong value)) { *dst = unchecked((byte)value); _matched++; }
            else _failed = true;
            return this;
        }
        // %c: default field width 1 (read exactly one byte); %s: unbounded unless capped.
        int max = width >= 0 ? width : (spec == (byte)'c' ? 1 : int.MaxValue);
        if (spec != (byte)'c') { SkipInputWs(); }
        // Hoisted once — CA2014 (no per-iteration stackalloc inside the loop).
        Span<char> chBuf = stackalloc char[1];
        Span<byte> b = stackalloc byte[4];
        int written = 0;
        int count = 0;
        while (count < max)
        {
            int peek = _r.Peek();
            if (peek == -1) { break; }
            if (spec == (byte)'s' && char.IsWhiteSpace((char)peek)) { break; }
            // ASCII fast path — caller's buffer is byte* (UTF-8). For
            // multi-byte chars, encode via Encoding.UTF8.
            int ch = _r.Read();
            count++;
            if (ch < 0x80)
            {
                dst[written++] = (byte)ch;
            }
            else
            {
                chBuf[0] = (char)ch;
                int n = Encoding.UTF8.GetBytes(chBuf, b);
                for (int i = 0; i < n; i++) { dst[written++] = b[i]; }
            }
        }
        if (spec != (byte)'c') { dst[written] = 0; }
        if (written > 0) { _matched++; } else _failed = true;
        return this;
    }

    /// <summary>Wide <c>%s</c> / <c>%c</c> target — a <c>wchar_t*</c> (= C#
    /// <c>char*</c>) for the <c>w*scanf</c> family. Mirrors <see cref="Read(byte*)"/>
    /// but stores UTF-16 code units straight from the reader (no UTF-8 encoding —
    /// the reader already yields UTF-16); <c>%s</c> stops at whitespace/EOF and
    /// NUL-terminates, <c>%c</c> reads a single unit (or <c>width</c> units). Narrow
    /// <c>scanf</c> never targets a <c>char*</c>, so this overload is wide-only.</summary>
    public ScanfReader Read(char* dst)
    {
        if (_failed) return this;
        var spec = ExpectSpec(out int width);
        if (_failed) return this;
        if (spec != (byte)'s' && spec != (byte)'c')
        {
            throw Unsupported(spec, "a wide string/char (%ls %lc)");
        }
        int max = width >= 0 ? width : (spec == (byte)'c' ? 1 : int.MaxValue);
        if (spec != (byte)'c') { SkipInputWs(); }
        int written = 0;
        while (written < max)
        {
            int peek = _r.Peek();
            if (peek == -1) { break; }
            if (spec == (byte)'s' && char.IsWhiteSpace((char)peek)) { break; }
            dst[written++] = (char)_r.Read();
        }
        if (spec != (byte)'c') { dst[written] = '\0'; }
        if (written > 0) { _matched++; } else _failed = true;
        return this;
    }

    public int Done() => _matched;

    /// <summary>Consume the next <c>%</c> spec from the format: skip leading fmt
    /// whitespace and matching input literals, suppressed conversions, the
    /// optional max field <paramref name="width"/>, and the length modifier;
    /// return the conversion letter (0 at end of format).</summary>
    private byte ExpectSpec(out int width)
    {
        width = -1;
        while (true)
        {
            while (*_fmt != 0)
            {
                if (IsAsciiWs(*_fmt)) { _fmt++; SkipInputWs(); continue; }
                if (*_fmt == '%' && _fmt[1] != '%') break;
                byte literal = *_fmt++;
                if (literal == '%') _fmt++;
                if (_r.Peek() != literal) { _failed = true; return 0; }
                _r.Read();
            }
            if (*_fmt != '%') return 0;
            _fmt++;
            bool suppress = *_fmt == '*';
            if (suppress) _fmt++;
            width = -1;
            while (*_fmt >= '0' && *_fmt <= '9')
            {
                if (width < 0) width = 0;
                width = width > (int.MaxValue - 9) / 10 ? int.MaxValue : width * 10 + (*_fmt - '0');
                _fmt++;
            }
            while (*_fmt is (byte)'l' or (byte)'L' or (byte)'h' or (byte)'z' or (byte)'j' or (byte)'t') _fmt++;
            byte spec = *_fmt;
            if (spec != 0) _fmt++;
            if (!suppress) return spec;
            if (spec == 's' || spec == 'c')
            {
                if (spec == 's') SkipInputWs();
                int remaining = width < 0 ? (spec == 'c' ? 1 : int.MaxValue) : width;
                bool any = false;
                while (remaining-- > 0 && _r.Peek() != -1 && (spec == 'c' || !char.IsWhiteSpace((char)_r.Peek())))
                { _r.Read(); any = true; }
                if (!any) { _failed = true; return 0; }
            }
            else if (!ReadIntegerValue(spec, width, out _)) { _failed = true; return 0; }
        }
    }

    private void SkipInputWs()
    {
        int c;
        while ((c = _r.Peek()) != -1 && char.IsWhiteSpace((char)c)) { _r.Read(); }
    }

    /// <summary>The value of ASCII digit <paramref name="c"/> in <paramref name="base"/>,
    /// or -1 if it is not a digit of that base.</summary>
    private static int DigitValue(int c, int @base)
    {
        int v = c switch
        {
            >= '0' and <= '9' => c - '0',
            >= 'a' and <= 'f' => c - 'a' + 10,
            >= 'A' and <= 'F' => c - 'A' + 10,
            _ => -1,
        };
        return v >= 0 && v < @base ? v : -1;
    }

    /// <summary>A loud, named failure for a conversion the routed overload can't
    /// satisfy — the dotcc "fail loudly, never silently wrong" contract for scanf.</summary>
    private static FormatException Unsupported(byte spec, string expected)
    {
        string s = spec == 0 ? "<end of format>" : "%" + (char)spec;
        return new FormatException(
            $"dotcc scanf: conversion '{s}' is not supported for {expected}. " +
            "Supported: %d %i %u %x %X %o (integer), %f %e %g (floating point), %s %c (string/char); " +
            "%n and %[...] scansets are not implemented.");
    }

    private static bool IsAsciiWs(byte b) => b is (byte)' ' or (byte)'\t' or (byte)'\r' or (byte)'\n';
}


#nullable restore
// ---- SecureZeroMemoryLib.cs ----
#nullable enable


public static unsafe partial class Libc
{
    /// <summary>Erase exactly count bytes, including buffers never read again.
    /// The caller owns writable unmanaged storage (or a pin) for the whole call.
    /// A null pointer is accepted for zero bytes. Success preserves errno.</summary>
    public static void explicit_bzero(void* destination, ulong count)
    {
        nuint remaining = ValidateMemoryRange(destination, count);
        byte* cursor = (byte*)destination;
        while (remaining != 0)
        {
            // Span lengths are signed int; C size_t is LP64. Validate the full
            // range before storing, then advance without narrowing the extent.
            int length = remaining > int.MaxValue ? int.MaxValue : (int)remaining;
            // ZeroMemory's documented contract retains writes even if no read
            // follows. Plain memset/Span.Clear alone does not give that contract.
            global::System.Security.Cryptography.CryptographicOperations.ZeroMemory(new Span<byte>(cursor, length));
            cursor += length;
            remaining -= (nuint)length;
        }
    }
}


#nullable restore
// ---- SelectLib.cs ----
#nullable enable


public static unsafe partial class Libc
{
    // Linux LP64 fd_set is 1024 bits, independent of the number of open fds.
    public static void FD_ZERO(void* set)
    {
        if (set != null) new Span<byte>(set, 128).Clear();
    }
    public static void FD_SET(int fd, void* set)
    {
        if (set != null && (uint)fd < 1024) ((ulong*)set)[fd / 64] |= 1UL << (fd % 64);
    }
    public static void FD_CLR(int fd, void* set)
    {
        if (set != null && (uint)fd < 1024) ((ulong*)set)[fd / 64] &= ~(1UL << (fd % 64));
    }
    public static int FD_ISSET(int fd, void* set) =>
        set != null && (uint)fd < 1024 && (((ulong*)set)[fd / 64] & (1UL << (fd % 64))) != 0 ? 1 : 0;

    private struct SelectPollFd { internal int Fd; internal short Events, Revents; }

    /// <summary>Select managed file, socket and pipe descriptors. The result
    /// counts ready bits across all sets; timeout is the Linux LP64 timeval and
    /// is reduced by elapsed monotonic time. Submillisecond waits round upward
    /// to the runtime scheduler's millisecond granularity.</summary>
    public static int select(int nfds, void* readfds, void* writefds, void* errorfds, void* timeout)
    {
        if ((uint)nfds > 1024) return FcntlError(EINVAL);
        long microseconds = -1;
        long originalSeconds = 0, originalMicros = 0;
        if (timeout != null)
        {
            long seconds = ((long*)timeout)[0], micros = ((long*)timeout)[1];
            if (seconds < 0 || micros < 0 || micros >= 1000000) return FcntlError(EINVAL);
            originalSeconds = seconds; originalMicros = micros;
            microseconds = seconds > (long.MaxValue - micros) / 1000000
                ? long.MaxValue : seconds * 1000000 + micros;
        }
        SelectPollFd* checks = stackalloc SelectPollFd[nfds];
        int count = 0;
        for (int fd = 0; fd < nfds; fd++)
        {
            short events = (short)(FD_ISSET(fd, readfds) | (FD_ISSET(fd, writefds) << 2) |
                (FD_ISSET(fd, errorfds) << 1));
            if (events != 0) checks[count++] = new() { Fd = fd, Events = events, Revents = 0 };
        }
        var elapsed = global::System.Diagnostics.Stopwatch.StartNew();
        long Remaining() => microseconds < 0 ? -1 : Math.Max(0, microseconds - (long)elapsed.Elapsed.TotalMicroseconds);
        while (true)
        {
            long remaining = Remaining();
            int millis = remaining < 0 ? -1 : (int)Math.Min(int.MaxValue, remaining / 1000 + (remaining % 1000 != 0 ? 1 : 0));
            int polled = poll(checks, (ulong)count, millis);
            if (polled < 0) return -1;
            int ready = 0;
            for (int i = 0; i < count; i++)
            {
                if ((checks[i].Revents & 32) != 0) return FcntlError(EBADF);
                short result = checks[i].Revents, wanted = checks[i].Events;
                if ((wanted & 1) != 0 && (result & (1 | 8 | 16)) != 0) ready++;
                if ((wanted & 4) != 0 && (result & (4 | 8)) != 0) ready++;
                if ((wanted & 2) != 0 && (result & 2) != 0) ready++;
            }
            if (ready != 0 || Remaining() == 0)
            {
                FD_ZERO(readfds); FD_ZERO(writefds); FD_ZERO(errorfds);
                for (int i = 0; i < count; i++)
                {
                    int fd = checks[i].Fd;
                    short result = checks[i].Revents, wanted = checks[i].Events;
                    if ((wanted & 1) != 0 && (result & (1 | 8 | 16)) != 0) FD_SET(fd, readfds);
                    if ((wanted & 4) != 0 && (result & (4 | 8)) != 0) FD_SET(fd, writefds);
                    if ((wanted & 2) != 0 && (result & 2) != 0) FD_SET(fd, errorfds);
                }
                if (timeout != null)
                {
                    long used = (long)elapsed.Elapsed.TotalMicroseconds;
                    long seconds = originalSeconds - used / 1000000;
                    long micros = originalMicros - used % 1000000;
                    if (micros < 0) { seconds--; micros += 1000000; }
                    ((long*)timeout)[0] = seconds < 0 ? 0 : seconds;
                    ((long*)timeout)[1] = seconds < 0 ? 0 : micros;
                }
                return ready;
            }
            // HUP/ERR are unconditional poll results, but aren't exceptional
            // data for select. A permanently hung-up exception-only descriptor
            // cannot gain urgent data; ignore it while waiting on the remainder.
            for (int i = 0; i < count; i++)
                if ((checks[i].Revents & (8 | 16)) != 0) checks[i].Fd = -1;
        }
    }
}


#nullable restore
// ---- SetJmpLib.cs ----
#nullable enable



/// <summary>
/// C99 <c>&lt;setjmp.h&gt;</c> surface, implemented via .NET exceptions.
/// </summary>
/// <remarks>
/// <para>
/// Real C's <c>setjmp</c> "returns twice" — once normally (0) and a
/// second time after <c>longjmp</c> (the longjmp value). That's
/// not expressible in structured C# control flow. The dotcc lowering
/// recognises specific syntactic patterns and rewrites them into a
/// <c>try / catch when</c> block. <c>longjmp</c> throws a
/// <see cref="JumpBufferException"/> carrying a numeric identity + value; the
/// <c>catch when</c> filter matches the identity captured at the right setjmp.
/// </para>
/// <para>
/// Supported syntactic shapes (the emitter recognises these and
/// rewrites; other shapes throw <c>CompileException</c>):
/// <list type="bullet">
///   <item><c>if (setjmp(env)) { recovery } else { normal }</c></item>
///   <item><c>if (setjmp(env) == 0) { normal } else { recovery }</c></item>
///   <item><c>switch (setjmp(env)) { case 0: …; case N: …; }</c> — VALUE
///     capture: the switch dispatches on the actual longjmp value.</item>
///   <item><c>int r = setjmp(env); switch (r) { … }</c> / <c>if (r == N) …</c>,
///     and <c>r = setjmp(env);</c> into a pre-declared simple variable.</item>
/// </list>
/// The value-capture shapes lower via a goto-restart: the enclosing region
/// re-runs from a synthetic label with <c>r</c> holding the jump value each
/// time a matching <c>longjmp</c> is caught — faithful "returns twice".
/// One bonus over real C: finally blocks DO run during the longjmp
/// unwind (.NET exception semantics). That's strictly better than
/// real <c>longjmp</c>, which silently skips through cleanup code —
/// a famous footgun.
/// </para>
/// </remarks>
public static unsafe partial class Libc
{
    private static long _nextJumpBufferIdentity;

    /// <summary>Arm an unmanaged identity slot for a newly executed setjmp.
    /// The returned identity is captured by the emitted handler, so neither a
    /// side-effecting buffer expression nor a later rearm changes its target.</summary>
    public static ulong ArmJumpBuffer(ulong* buffer)
    {
        if (buffer == null) throw new ArgumentNullException(nameof(buffer));
        long previous, next;
        do
        {
            previous = Volatile.Read(ref _nextJumpBufferIdentity);
            if (previous == long.MaxValue)
                throw new InvalidOperationException("Nonlocal jump identity space exhausted.");
            next = previous + 1;
        } while (Interlocked.CompareExchange(ref _nextJumpBufferIdentity, next, previous) != previous);
        *buffer = (ulong)next;
        return (ulong)next;
    }

    /// <summary>Managed exception transport for an unmanaged C jump buffer.
    /// Only the numeric identity and return value cross the unwind boundary.</summary>
    public sealed class JumpBufferException : Exception
    {
        public ulong Identity { get; }
        public int Value { get; }
        internal RuntimeContext? OriginOwner { get; }
        internal int OriginThread { get; }
        public JumpBufferException(ulong identity, int value)
            : base($"longjmp(value={value})")
        {
            Identity = identity;
            Value = value;
            OriginOwner = RuntimeContext.Current;
            OriginThread = Environment.CurrentManagedThreadId;
        }
    }

    /// <summary>The emitter handles setjmp's returns-twice semantics. A direct
    /// runtime call cannot establish a resumable handler and fails explicitly.</summary>
    public static int setjmp(ulong* buffer)
        => throw new InvalidOperationException("setjmp requires compiler control-flow lowering.");

    /// <summary>Only the compiler can establish the lexical returns-twice region.</summary>
    public static int sigsetjmp(ulong* buffer, int saveMask)
        => throw new InvalidOperationException("sigsetjmp requires compiler control-flow lowering.");

    /// <summary>The matching lexical activation owns signal-mask restoration.
    /// Zero is normalized by the same numeric transport as ordinary longjmp.</summary>
    public static void siglongjmp(ulong* buffer, int value) => longjmp(buffer, value);

    public static void longjmp(ulong* buffer, int value)
    {
        if (buffer == null) throw new ArgumentNullException(nameof(buffer));
        ulong identity = *buffer;
        if (identity == 0)
            throw new InvalidOperationException("longjmp requires an armed jump buffer.");
        throw new JumpBufferException(identity, value == 0 ? 1 : value);
    }

    /// <summary>
    /// Legacy managed API token retained for existing direct callers. The C
    /// header now uses an unmanaged numeric slot and never stores this class
    /// in translated C memory.
    /// </summary>
    public sealed class LongJmpToken { }

    /// <summary>
    /// Exception carrying a non-local jump's target + value. Thrown
    /// by <see cref="longjmp(LongJmpToken, int)"/>; caught by the
    /// emitter-generated <c>catch when (__jmp.Token == env)</c>.
    /// </summary>
    public sealed class LongJmpException : Exception
    {
        public LongJmpToken Token { get; }
        public int Value { get; }
        public LongJmpException(LongJmpToken token, int value)
            : base($"longjmp(value={value})")
        {
            Token = token;
            Value = value;
        }
    }

    /// <summary>
    /// <c>setjmp(env)</c>. The function ALWAYS returns 0 on its
    /// direct call (it's the post-longjmp re-entry that returns the
    /// value, and that's handled by the emitter's try/catch
    /// rewrite). User code that pattern-matches the result against
    /// 0 vs non-zero gets the right behaviour after the rewrite.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static int setjmp(LongJmpToken env) => 0;

    /// <summary>
    /// <c>longjmp(env, value)</c>. Throws a
    /// <see cref="LongJmpException"/> tagged with <paramref name="env"/>.
    /// The emitter-generated <c>catch when (__jmp.Token == env)</c>
    /// at the matching <c>setjmp</c> site catches it, exposes the
    /// value, and resumes execution in the recovery branch.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static void longjmp(LongJmpToken env, int value)
        => throw new LongJmpException(env, value == 0 ? 1 : value);
}


