#nullable enable



/// <summary>
/// C <c>&lt;wchar.h&gt;</c> wide-string and wide-memory surface. dotcc's
/// <c>wchar_t</c> is the MSVC shape — an unsigned 16-bit UTF-16 code unit lowered
/// to C# <c>char</c> — so every function here is the direct 16-bit sibling of its
/// <see cref="Libc">byte</see> counterpart in <see cref="Libc">Libc.cs</see> /
/// <c>StringLib.cs</c>: a bare <c>char*</c> loop over NUL-terminated UTF-16
/// buffers (no GC allocation), exactly mirroring how the <c>str*</c>/<c>mem*</c>
/// family walks <c>byte*</c>.
/// </summary>
/// <remarks>
/// The numeric parsers (<see cref="wcstol"/> et al.) don't reimplement C's
/// strtol/strtod grammar — they transcode the leading ASCII run to a scratch byte
/// buffer and delegate to the battle-tested byte cores (full C semantics: base
/// 0/2-36, <c>errno</c>+clamp on overflow, hex floats, <c>inf</c>/<c>nan</c>),
/// then map the byte endptr back onto the wide pointer.
///
/// Wide character/line I/O (<c>fputwc</c>/<c>fgetwc</c>/<c>fputws</c>/<c>fgetws</c>/…)
/// and wide formatted I/O (<c>wprintf</c>/<c>fwprintf</c>/<c>swprintf</c> and the
/// <c>w*scanf</c> family) are provided too — see further down. Output goes through
/// the stream's UTF-8 <c>TextWriter</c>; input assembles UTF-8 off the byte reader;
/// the formatted family transcodes the wide format to UTF-8 and reuses the byte
/// <see cref="PrintfBuilder"/>/<see cref="ScanfReader"/>. NOT provided: the explicit
/// multibyte&lt;-&gt;wide conversion model (<c>mbrtowc</c> / <c>wcrtomb</c> /
/// <c>mbstate_t</c>). dotcc maps C <c>size_t</c> to <c>ulong</c>; length-returning
/// functions narrow to <c>int</c> to match <see cref="Libc.strlen"/>.
/// </remarks>
public static unsafe partial class Libc
{
    // ---------------------------------------------------------------------
    // Length / comparison / copy
    // ---------------------------------------------------------------------

    /// <summary><c>wcslen(s)</c> — code units before the first <c>0</c> in
    /// <paramref name="s"/> (the wide <see cref="strlen"/>).</summary>
    public static int wcslen(char* s)
    {
        int n = 0;
        while (s[n] != 0) { n++; }
        return n;
    }

    /// <summary><c>wcscmp(a, b)</c> — lexicographic compare by code unit; returns
    /// 0 / negative / positive (the wide <see cref="strcmp(byte*, byte*)"/>).</summary>
    public static int wcscmp(char* a, char* b)
    {
        while (*a != 0 && *a == *b) { a++; b++; }
        return *a - *b;
    }

    /// <summary><c>wcsncmp(a, b, n)</c> — compare at most <paramref name="n"/>
    /// code units; stops early at a mismatch or a shared NUL.</summary>
    public static int wcsncmp(char* a, char* b, ulong n)
    {
        for (ulong i = 0; i < n; i++)
        {
            if (a[i] != b[i]) { return a[i] - b[i]; }
            if (a[i] == 0) { return 0; }
        }
        return 0;
    }

    /// <summary><c>wcscoll(a, b)</c> — locale-aware compare. dotcc runs the
    /// <c>"C"</c> locale, where collation is plain code-unit order, so this is
    /// exactly <see cref="wcscmp"/>.</summary>
    public static int wcscoll(char* a, char* b) => wcscmp(a, b);

    /// <summary><c>wcscpy(dst, src)</c> — copy NUL-terminated <paramref name="src"/>
    /// (including the terminating <c>0</c>) into <paramref name="dst"/>. Returns
    /// <paramref name="dst"/>.</summary>
    public static char* wcscpy(char* dst, char* src)
    {
        char* p = dst;
        while ((*p++ = *src++) != 0) { }
        return dst;
    }

    /// <summary><c>wcsncpy(dst, src, n)</c> — copy up to <paramref name="n"/> code
    /// units; if <paramref name="src"/> is shorter, NUL-pad to <paramref name="n"/>;
    /// if it is <paramref name="n"/> or longer, <em>no</em> terminating NUL is
    /// written (the classic strncpy footgun, faithfully reproduced). Returns
    /// <paramref name="dst"/>.</summary>
    public static char* wcsncpy(char* dst, char* src, ulong n)
    {
        ulong i = 0;
        for (; i < n && src[i] != 0; i++) { dst[i] = src[i]; }
        for (; i < n; i++) { dst[i] = '\0'; }
        return dst;
    }

    // ---------------------------------------------------------------------
    // Concatenation
    // ---------------------------------------------------------------------

    /// <summary><c>wcscat(dst, src)</c> — append NUL-terminated <paramref name="src"/>
    /// to the end of <paramref name="dst"/>, re-terminating. Returns
    /// <paramref name="dst"/>.</summary>
    public static char* wcscat(char* dst, char* src)
    {
        char* p = dst;
        while (*p != 0) { p++; }
        while ((*p++ = *src++) != 0) { }
        return dst;
    }

    /// <summary><c>wcsncat(dst, src, n)</c> — append at most <paramref name="n"/>
    /// code units of <paramref name="src"/>, then always write a terminating NUL.
    /// Returns <paramref name="dst"/>.</summary>
    public static char* wcsncat(char* dst, char* src, ulong n)
    {
        char* p = dst;
        while (*p != 0) { p++; }
        ulong i = 0;
        for (; i < n && src[i] != 0; i++) { p[i] = src[i]; }
        p[i] = '\0';
        return dst;
    }

    // ---------------------------------------------------------------------
    // Search
    // ---------------------------------------------------------------------

    /// <summary><c>wcschr(s, c)</c> — first occurrence of code unit
    /// <paramref name="c"/> in <paramref name="s"/>, or <c>null</c>. The
    /// terminating NUL is part of the string, so <c>wcschr(s, 0)</c> finds it.</summary>
    public static char* wcschr(char* s, char c)
    {
        while (true)
        {
            if (*s == c) { return s; }
            if (*s == 0) { return null; }
            s++;
        }
    }

    /// <summary><c>wcsrchr(s, c)</c> — last occurrence of <paramref name="c"/> in
    /// <paramref name="s"/>, or <c>null</c>. <c>wcsrchr(s, 0)</c> finds the NUL.</summary>
    public static char* wcsrchr(char* s, char c)
    {
        char* last = null;
        while (true)
        {
            if (*s == c) { last = s; }
            if (*s == 0) { return last; }
            s++;
        }
    }

    /// <summary><c>wcsstr(haystack, needle)</c> — first occurrence of
    /// <paramref name="needle"/> in <paramref name="haystack"/>, or <c>null</c>.
    /// An empty needle matches at the start.</summary>
    public static char* wcsstr(char* haystack, char* needle)
    {
        if (*needle == 0) { return haystack; }
        for (char* h = haystack; *h != 0; h++)
        {
            char* a = h;
            char* b = needle;
            while (*a != 0 && *b != 0 && *a == *b) { a++; b++; }
            if (*b == 0) { return h; }
        }
        return null;
    }

    /// <summary>Whether the NUL-terminated wide <paramref name="set"/> contains code
    /// unit <paramref name="c"/> — the inner scan of wcsspn/wcscspn/wcspbrk.</summary>
    private static bool WcsSetContains(char* set, char c)
    {
        for (char* p = set; *p != 0; p++) { if (*p == c) { return true; } }
        return false;
    }

    /// <summary><c>wcsspn(s, accept)</c> — length of the initial run of
    /// <paramref name="s"/> consisting only of code units from
    /// <paramref name="accept"/>.</summary>
    public static int wcsspn(char* s, char* accept)
    {
        int n = 0;
        while (s[n] != 0 && WcsSetContains(accept, s[n])) { n++; }
        return n;
    }

    /// <summary><c>wcscspn(s, reject)</c> — length of the initial run of
    /// <paramref name="s"/> containing no code unit from
    /// <paramref name="reject"/>.</summary>
    public static int wcscspn(char* s, char* reject)
    {
        int n = 0;
        while (s[n] != 0 && !WcsSetContains(reject, s[n])) { n++; }
        return n;
    }

    /// <summary><c>wcspbrk(s, accept)</c> — pointer to the first code unit of
    /// <paramref name="s"/> that is in <paramref name="accept"/>, or <c>null</c>.</summary>
    public static char* wcspbrk(char* s, char* accept)
    {
        for (char* p = s; *p != 0; p++) { if (WcsSetContains(accept, *p)) { return p; } }
        return null;
    }

    /// <summary><c>wcstok(str, delim, saveptr)</c> — C's wide tokenizer, which is
    /// reentrant by signature (an explicit <c>wchar_t**</c> save slot, unlike the
    /// stateful narrow <see cref="strtok"/>). First call passes the string; later
    /// calls pass <c>NULL</c> to resume from <paramref name="saveptr"/>. Writes a
    /// NUL over each consumed delimiter. Returns the next token, or <c>null</c>.</summary>
    public static char* wcstok(char* str, char* delim, char** saveptr)
    {
        char* s = str != null ? str : *saveptr;
        if (s == null) { return null; }
        // Skip leading delimiters.
        while (*s != 0 && WcsSetContains(delim, *s)) { s++; }
        if (*s == 0) { *saveptr = s; return null; }
        char* token = s;
        // Run to the next delimiter or the end.
        while (*s != 0 && !WcsSetContains(delim, *s)) { s++; }
        if (*s != 0) { *s = '\0'; s++; }
        *saveptr = s;
        return token;
    }

    // ---------------------------------------------------------------------
    // Wide-memory ops (counts are in wchar_t units, not bytes)
    // ---------------------------------------------------------------------

    /// <summary><c>wmemcpy(dst, src, n)</c> — copy <paramref name="n"/> code units.
    /// Returns <paramref name="dst"/>.</summary>
    public static char* wmemcpy(char* dst, char* src, ulong n)
    {
        ulong bytes = n * (ulong)sizeof(char);
        Buffer.MemoryCopy(src, dst, bytes, bytes);
        return dst;
    }

    /// <summary><c>wmemmove(dst, src, n)</c> — copy <paramref name="n"/> code units,
    /// overlap-safe. Returns <paramref name="dst"/>.</summary>
    public static char* wmemmove(char* dst, char* src, ulong n)
    {
        ulong bytes = n * (ulong)sizeof(char);
        Buffer.MemoryCopy(src, dst, bytes, bytes);   // overlap-safe
        return dst;
    }

    /// <summary><c>wmemset(dst, c, n)</c> — fill <paramref name="n"/> code units of
    /// <paramref name="dst"/> with <paramref name="c"/>. Returns
    /// <paramref name="dst"/>.</summary>
    public static char* wmemset(char* dst, char c, ulong n)
    {
        for (ulong i = 0; i < n; i++) { dst[i] = c; }
        return dst;
    }

    /// <summary><c>wmemcmp(a, b, n)</c> — compare <paramref name="n"/> code units;
    /// signed difference of the first differing pair, or 0.</summary>
    public static int wmemcmp(char* a, char* b, ulong n)
    {
        for (ulong i = 0; i < n; i++)
        {
            if (a[i] != b[i]) { return a[i] - b[i]; }
        }
        return 0;
    }

    /// <summary><c>wmemchr(s, c, n)</c> — pointer to the first occurrence of
    /// <paramref name="c"/> within the first <paramref name="n"/> code units of
    /// <paramref name="s"/>, or <c>null</c>.</summary>
    public static char* wmemchr(char* s, char c, ulong n)
    {
        for (ulong i = 0; i < n; i++)
        {
            if (s[i] == c) { return s + i; }
        }
        return null;
    }

    // ---------------------------------------------------------------------
    // Wide → number conversions
    //
    // The wide numeric grammar (whitespace, sign, base prefix, digits, decimal
    // point, exponent, inf/nan) is entirely ASCII, so each parser copies the
    // leading <= 0x7F run into a scratch byte buffer and delegates to the byte
    // core — full C semantics already live there (base 0/2-36, errno+clamp on
    // overflow, C99 hex floats, inf/nan). One ASCII code unit maps to one byte,
    // so the byte endptr offset translates straight back onto the wide pointer.
    // ---------------------------------------------------------------------

    /// <summary>Allocate a NUL-terminated byte copy of the leading ASCII run of
    /// wide string <paramref name="nptr"/> (stopping at the first &gt; 0x7F unit or
    /// the NUL — neither can be part of a number, so it's a valid boundary). The
    /// caller must <see cref="NativeMemory.Free(void*)"/> the result.</summary>
    private static byte* WideNumericScratch(char* nptr)
    {
        int n = 0;
        while (nptr[n] != 0 && nptr[n] <= 0x7F) { n++; }
        byte* buf = (byte*)NativeMemory.Alloc((nuint)n + 1);
        for (int i = 0; i < n; i++) { buf[i] = (byte)nptr[i]; }
        buf[n] = 0;
        return buf;
    }

    /// <summary>Run <paramref name="nptr"/> through the byte signed-integer core and
    /// translate the endptr back to the wide pointer (shared by wcstol/wcstoll).</summary>
    private static long WcstollViaByte(char* nptr, char** endptr, int @base)
    {
        byte* buf = WideNumericScratch(nptr);
        byte* bEnd;
        long v = strtol(buf, &bEnd, @base);
        if (endptr != null) { *endptr = nptr + (bEnd - buf); }
        NativeMemory.Free(buf);
        return v;
    }

    /// <summary>Run <paramref name="nptr"/> through the byte unsigned-integer core and
    /// translate the endptr back to the wide pointer (shared by wcstoul/wcstoull).</summary>
    private static ulong WcstoullViaByte(char* nptr, char** endptr, int @base)
    {
        byte* buf = WideNumericScratch(nptr);
        byte* bEnd;
        ulong v = strtoul(buf, &bEnd, @base);
        if (endptr != null) { *endptr = nptr + (bEnd - buf); }
        NativeMemory.Free(buf);
        return v;
    }

    /// <summary>Run <paramref name="nptr"/> through the byte floating-point core and
    /// translate the endptr back to the wide pointer (shared by wcstod/wcstof/wcstold).</summary>
    private static double WcstodViaByte(char* nptr, char** endptr)
    {
        byte* buf = WideNumericScratch(nptr);
        byte* bEnd;
        double v = strtod(buf, &bEnd);
        if (endptr != null) { *endptr = nptr + (bEnd - buf); }
        NativeMemory.Free(buf);
        return v;
    }

    /// <summary><c>wcstol(nptr, endptr, base)</c> — parse a signed long.</summary>
    public static long wcstol(char* nptr, char** endptr, int @base) => WcstollViaByte(nptr, endptr, @base);

    /// <summary><c>wcstoll(nptr, endptr, base)</c> (C99) — signed long long
    /// (== <c>wcstol</c> on dotcc's LP64 model).</summary>
    public static long wcstoll(char* nptr, char** endptr, int @base) => WcstollViaByte(nptr, endptr, @base);

    /// <summary><c>wcstoul(nptr, endptr, base)</c> — parse an unsigned long.</summary>
    public static ulong wcstoul(char* nptr, char** endptr, int @base) => WcstoullViaByte(nptr, endptr, @base);

    /// <summary><c>wcstoull(nptr, endptr, base)</c> (C99) — unsigned long long.</summary>
    public static ulong wcstoull(char* nptr, char** endptr, int @base) => WcstoullViaByte(nptr, endptr, @base);

    /// <summary><c>wcstod(nptr, endptr)</c> — parse a double (sign, decimal point,
    /// <c>e</c>/<c>E</c> exponent, C99 hex floats, <c>inf</c>/<c>nan</c>).</summary>
    public static double wcstod(char* nptr, char** endptr) => WcstodViaByte(nptr, endptr);

    /// <summary><c>wcstof(nptr, endptr)</c> (C99) — parse a float (the double parse,
    /// narrowed to <see cref="float"/>).</summary>
    public static float wcstof(char* nptr, char** endptr) => (float)WcstodViaByte(nptr, endptr);

    /// <summary><c>wcstold(nptr, endptr)</c> (C99) — parse a long double
    /// (== <c>double</c> on dotcc's model).</summary>
    public static double wcstold(char* nptr, char** endptr) => WcstodViaByte(nptr, endptr);

    // ---------------------------------------------------------------------
    // Wide character / line I/O
    //
    // dotcc's narrow encoding is UTF-8, so wide I/O is UTF-8<->UTF-16. Output
    // goes through the stream's TextWriter (WriterFor) — the same unbuffered
    // UTF-8 writer fprintf uses, so wide and narrow writes on one handle stay
    // ordered. Input assembles UTF-8 off the byte reader (ReadWideFrom),
    // byte-stream-consistent with fgetc/fgets (shared bytes + ungetc pushback).
    // Wide FORMATTED I/O (wprintf / w*scanf) is handled by the emitter — see
    // the printf/scanf fluent lowering — not here.
    // ---------------------------------------------------------------------

    /// <summary><c>fputwc(c, stream)</c> — write the wide character
    /// <paramref name="c"/> (UTF-8-encoded) to <paramref name="stream"/>; returns
    /// it, or <c>WEOF</c> on a non-output stream.</summary>
    public static int fputwc(char c, FILE* stream)
    {
        WriterFor(stream).Write(c);
        return c;
    }

    /// <summary><c>putwc(c, stream)</c> — identical to <see cref="fputwc"/>.</summary>
    public static int putwc(char c, FILE* stream) => fputwc(c, stream);

    /// <summary><c>putwchar(c)</c> ≡ <c>fputwc(c, stdout)</c>.</summary>
    public static int putwchar(char c) => fputwc(c, stdout);

    /// <summary><c>fputws(s, stream)</c> — write NUL-terminated wide string
    /// <paramref name="s"/> (UTF-8-encoded) to <paramref name="stream"/>; no
    /// newline (per C — only the never-standardised wide <c>puts</c> would add one).
    /// Returns a non-negative value on success.</summary>
    public static int fputws(char* s, FILE* stream)
    {
        if (s == null) { return -1; }
        WriterFor(stream).Write(new string(s, 0, wcslen(s)));
        return 0;
    }

    /// <summary><c>fgetwc(stream)</c> — read one wide character from
    /// <paramref name="stream"/> (decoding a UTF-8 multibyte sequence; a code point
    /// above U+FFFF arrives as two calls, the surrogate pair). Returns the code unit
    /// (0..0xFFFF) or <c>WEOF</c> (-1) at end of input.</summary>
    public static int fgetwc(FILE* stream) => ReadWideFrom(stream);

    /// <summary><c>getwc(stream)</c> — identical to <see cref="fgetwc"/>.</summary>
    public static int getwc(FILE* stream) => fgetwc(stream);

    /// <summary><c>getwchar()</c> ≡ <c>fgetwc(stdin)</c>.</summary>
    public static int getwchar() => fgetwc(stdin);

    /// <summary><c>ungetwc(c, stream)</c> — push one wide character back so the next
    /// <see cref="fgetwc"/> returns it. One pushback only; <c>WEOF</c> can't be
    /// pushed. Returns <paramref name="c"/> or <c>WEOF</c> on failure.</summary>
    public static int ungetwc(int c, FILE* stream) => UngetWideTo(stream, c);

    /// <summary><c>fgetws(s, n, stream)</c> — read at most <c><paramref name="n"/>-1</c>
    /// wide characters into <paramref name="s"/>, stopping after a newline (which is
    /// kept) or at end of input, then NUL-terminate. Returns <paramref name="s"/>, or
    /// <c>null</c> if end of input is hit before any character (the wide
    /// <see cref="fgets"/>).</summary>
    public static char* fgetws(char* s, int n, FILE* stream)
    {
        if (n <= 0) { return null; }
        int i = 0;
        while (i < n - 1)
        {
            int ch = ReadWideFrom(stream);
            if (ch < 0)
            {
                if (i == 0) { return null; }   // EOF with nothing read
                break;
            }
            s[i++] = (char)ch;
            if (ch == '\n') { break; }
        }
        s[i] = '\0';
        return s;
    }

    // ---------------------------------------------------------------------
    // Wide formatted output (wprintf / fwprintf / swprintf)
    //
    // The emitter lowers these to the SAME fluent builder as printf/sprintf
    // (see CSharpBackend's printf-family lowering). The wide format is
    // transcoded to UTF-8 (so the byte PrintfBuilder parses the identical spec
    // grammar); only a wide %s arg differs, handled by PrintfBuilder.Arg(char*).
    // Wide formatted INPUT (w*scanf) lowers the same way to ScanfReader.
    // ---------------------------------------------------------------------

    private static readonly global::System.Collections.Concurrent.ConcurrentDictionary<IntPtr, IntPtr> _wideFmtToUtf8 =
        new();

    /// <summary>Transcode a wide (UTF-16) printf/scanf format to a pinned,
    /// NUL-terminated UTF-8 <c>byte*</c> so the byte <see cref="PrintfBuilder"/> /
    /// <see cref="ScanfReader"/> parses it unchanged. Pooled by the wide pointer — a
    /// .rodata-style pool transcoded once per distinct literal (a format is ~always
    /// an <c>L"…"</c> literal; a mutable runtime format reusing an address is
    /// unsupported).</summary>
    private static byte* WideFmtToUtf8(char* wfmt)
    {
        var key = (IntPtr)wfmt;
        if (_wideFmtToUtf8.TryGetValue(key, out var hit)) { return (byte*)hit; }   // lock-free hot path
        // Miss: transcode + allocate, then publish atomically with the value-taking
        // GetOrAdd. Two threads racing the same new key both allocate; the loser
        // frees its buffer (otherwise the dropped NativeMemory block would leak — the
        // reason a value cache like this can't use the naive factory GetOrAdd).
        var bytes = global::System.Text.Encoding.UTF8.GetBytes(new string(wfmt, 0, wcslen(wfmt)));
        byte* buf = (byte*)NativeMemory.Alloc((nuint)bytes.Length + 1);
        for (int i = 0; i < bytes.Length; i++) { buf[i] = bytes[i]; }
        buf[bytes.Length] = 0;
        var actual = _wideFmtToUtf8.GetOrAdd(key, (IntPtr)buf);
        if (actual != (IntPtr)buf) { NativeMemory.Free(buf); }   // lost the race → free ours
        return (byte*)actual;
    }

    /// <summary><c>wprintf(fmt, …)</c> — wide formatted output to stdout. The emitter
    /// expands the variadic tail into the fluent <c>.Arg(…).Done()</c> chain.</summary>
    public static PrintfBuilder wprintf(char* fmt) => new PrintfBuilder(WriterFor(stdout), WideFmtToUtf8(fmt));

    /// <summary><c>fwprintf(stream, fmt, …)</c> — wide formatted output to a stream.</summary>
    public static PrintfBuilder fwprintf(FILE* stream, char* fmt) => new PrintfBuilder(WriterFor(stream), WideFmtToUtf8(fmt));

    /// <summary><c>swprintf(s, n, fmt, …)</c> — wide formatted output into
    /// <paramref name="s"/>, at most <paramref name="n"/> wide chars including the
    /// terminating NUL (returns a negative value if it doesn't fit — C's swprintf
    /// contract, unlike snprintf).</summary>
    public static WSprintfBuilder swprintf(char* s, ulong n, char* fmt) => new WSprintfBuilder(s, WideFmtToUtf8(fmt), (int)n);

    // ---------------------------------------------------------------------
    // Wide formatted input (wscanf / fwscanf / swscanf)
    //
    // The emitter lowers these to the same fluent .Read(ptr).Done() chain as
    // scanf/sscanf. The wide format is transcoded to UTF-8 so the byte
    // ScanfReader parses it unchanged; a wide %s/%c target is a char* (UTF-16),
    // handled by ScanfReader.Read(char*). swscanf wraps its wide source string in
    // a StringReader, exactly as sscanf does for a byte source.
    // ---------------------------------------------------------------------

    /// <summary><c>wscanf(fmt, …)</c> ≡ <c>fwscanf(stdin, fmt, …)</c>.</summary>
    public static ScanfReader wscanf(char* fmt) => fwscanf(stdin, fmt);

    /// <summary><c>fwscanf(stream, fmt, …)</c> — wide formatted input from a stream.</summary>
    public static ScanfReader fwscanf(FILE* stream, char* fmt) => new ScanfReader(ReaderFor(stream), WideFmtToUtf8(fmt));

    /// <summary><c>swscanf(src, fmt, …)</c> — wide formatted input from the wide
    /// string <paramref name="src"/> (wrapped in a reader, like sscanf).</summary>
    public static ScanfReader swscanf(char* src, char* fmt) =>
        new ScanfReader(new StringReader(new string(src, 0, wcslen(src))), WideFmtToUtf8(fmt));
}


#nullable restore
// ---- ZigAlloc.cs ----
#nullable enable


/// <summary>
/// The runtime backing for the Zig front-end's allocators (Milestone F) — the shared
/// <c>std.mem.Allocator</c> abstraction. Auto-spliced into every emitted program (the
/// <c>DotCC.Libc/*.cs</c> <c>&lt;EmbeddedResource&gt;</c> glob) and compiled into
/// <c>DotCC.Libc.dll</c> for the unit tests, exactly like <see cref="Slice{T}"/> /
/// <see cref="ErrUnion{T}"/>.
/// </summary>
/// <remarks>
/// <para>
/// Zig's <c>std.mem.Allocator</c> is a fat pointer <c>{ ptr, *vtable }</c> whose high-level
/// generic methods (<c>alloc</c>/<c>free</c>) dispatch through a vtable of raw byte-level
/// function pointers. dotcc mirrors that shape with <see cref="Allocator"/> (the fat pointer),
/// <see cref="AllocatorVTable"/> (the fn-ptr table), and a second concrete allocator,
/// <see cref="FixedBufferAllocator"/>, to exercise genuine indirect dispatch.
/// </para>
/// <para>
/// <b>Devirtualization.</b> When the lowering can PROVE the allocator is the statically-known
/// C-heap default (<c>std.heap.page_allocator</c> / <c>std.heap.c_allocator</c>), it bypasses
/// the vtable entirely and emits a direct call to <see cref="AllocCHeap{T}"/> /
/// <see cref="FreeCHeap{T}"/> (which reach <see cref="Libc.malloc"/>/<see cref="Libc.free"/>
/// with no indirection). A runtime-selected allocator (an opaque <c>std.mem.Allocator</c>
/// parameter, or a <see cref="FixedBufferAllocator"/>'s <see cref="FbaAllocator"/> result) pays
/// the indirect <c>delegate*</c> dispatch through <see cref="Allocator.Alloc{T}"/> /
/// <see cref="Allocator.Free{T}"/> instead. Both paths produce the same
/// <c>ErrUnion&lt;Slice&lt;T&gt;&gt;</c>, so they compose with <c>try</c>/<c>catch</c>.
/// </para>
/// <para>
/// The vtable function pointers are MANAGED (<c>delegate*&lt;…&gt;</c>, not
/// <c>unmanaged[Cdecl]</c>): an <see cref="Allocator"/> never crosses a real C ABI (it is a
/// Zig-internal abstraction), and a managed function pointer targets a plain <c>static</c>
/// method with no <c>[UnmanagedCallersOnly]</c> ceremony, which keeps the whole file
/// AOT-clean. The vtable is carried <b>by value</b> inside <see cref="Allocator"/> (rather
/// than a <c>*const VTable</c>) so there is no managed-static address to pin. Each method
/// address is captured once in a static readonly table; materialization copies those
/// canonical pointer bits, preserving identity across JIT entry-point changes.
/// </para>
/// </remarks>
public unsafe struct AllocatorVTable
{
    /// <summary>Raw allocation: <c>(ctx, len, alignment, ret_addr) → ?[*]u8</c>; null on failure.
    /// Mirrors Zig's <c>VTable.alloc</c> exactly (the field name matches, so a user
    /// <c>std.mem.Allocator.VTable{ .alloc = … }</c> literal binds 1:1).</summary>
    public delegate*<void*, ulong, Alignment, ulong, byte*> alloc;

    /// <summary>In-place resize: <c>(ctx, memory: []u8, alignment, new_len, ret_addr) → bool</c>.
    /// dotcc's own <c>realloc</c> emulates via alloc+copy+free; std code reaches this through
    /// <c>a.rawResize</c> (<see cref="ZigAlloc.RawResize"/>) and <c>a.resize</c>.</summary>
    public delegate*<void*, Slice<byte>, Alignment, ulong, ulong, CBool> resize;

    /// <summary>Resize-possibly-moving: <c>(ctx, memory: []u8, alignment, new_len, ret_addr) → ?[*]u8</c>.
    /// Reached through <c>a.rawRemap</c> (<see cref="ZigAlloc.RawRemap"/>, std.Io.Writer.Allocating) and <c>a.remap</c>.</summary>
    public delegate*<void*, Slice<byte>, Alignment, ulong, ulong, byte*> remap;

    /// <summary>Raw free: <c>(ctx, memory: []u8, alignment, ret_addr) → void</c>.</summary>
    public delegate*<void*, Slice<byte>, Alignment, ulong, void> free;
}

/// <summary>
/// Models Zig's <c>std.mem.Alignment</c> (Milestone W) — a power-of-two byte alignment threaded
/// through the allocator vtable. Real zig stores <c>log2(bytes)</c> in an <c>enum(u6)</c>; dotcc
/// carries the byte count directly and exposes <see cref="toByteUnits"/> (identity). The
/// <see cref="FixedBufferAllocator"/> genuinely honors the request (it aligns its bump pointer up);
/// the C heap and arena over-align (≥16-aligned) and dotcc's <see cref="ZigAlloc.AlignOf{T}"/> caps
/// requests at 16, so on those two the exact value is satisfied by construction. <b>Cut:</b>
/// <c>@intFromEnum</c> (the log2) is not modeled — use <c>.toByteUnits()</c>.
/// </summary>
public readonly struct Alignment
{
    private readonly ulong _bytes;

    /// <summary>Construct an alignment of <paramref name="bytes"/> bytes (a power of two).</summary>
    public Alignment(ulong bytes) { _bytes = bytes; }

    /// <summary>Zig's <c>Alignment.toByteUnits()</c> — the alignment in bytes.</summary>
    public ulong toByteUnits() => _bytes;

    /// <summary>Zig's <c>Alignment.fromByteUnits(n)</c> — the alignment of <paramref name="bytes"/> bytes (a
    /// power of two), as std's hash_map spells its buffer alignment (<c>comptime .fromByteUnits(…)</c>).</summary>
    public static Alignment fromByteUnits(ulong bytes) => new(bytes);

    /// <summary><c>a.toByteUnits()</c> called on a curated <c>std.mem.Alignment</c> value (emitted statically).</summary>
    public static ulong ToByteUnits(Alignment a) => a._bytes;

    /// <summary><c>a.forward(address)</c> — <paramref name="address"/> rounded UP to the alignment.</summary>
    public static ulong Forward(Alignment a, ulong address) => (address + a._bytes - 1) & ~(a._bytes - 1);

    /// <summary><c>a.backward(address)</c> — <paramref name="address"/> rounded DOWN to the alignment.</summary>
    public static ulong Backward(Alignment a, ulong address) => address & ~(a._bytes - 1);

    /// <summary><c>a.check(address)</c> — whether <paramref name="address"/> is aligned.</summary>
    public static bool Check(Alignment a, ulong address) => (address & (a._bytes - 1)) == 0;
}

/// <summary>
/// The Zig <c>std.mem.Allocator</c> fat pointer — an opaque context <see cref="Ctx"/> plus a
/// vtable of raw byte-level allocation function pointers. The high-level generic
/// <see cref="Alloc{T}"/> / <see cref="Free{T}"/> compute element sizes and wrap the raw
/// results in a <see cref="Slice{T}"/> / <see cref="ErrUnion{T}"/>, dispatching through the
/// vtable (the indirect path; the devirt path on <see cref="ZigAlloc"/> bypasses this).
/// </summary>
public unsafe struct Allocator
{
    /// <summary>The opaque allocator context (e.g. a <c>FixedBufferAllocator*</c>; null for
    /// the stateless C heap).</summary>
    public void* Ctx;

    /// <summary>The raw allocation function pointers (carried by value — see the file remarks).</summary>
    public AllocatorVTable Vtable;

    /// <summary><c>a.alloc(T, n)</c> — allocate <paramref name="n"/> elements of
    /// <typeparamref name="T"/> through the vtable. Returns a <see cref="Slice{T}"/> on
    /// success, or the error code <paramref name="oom"/> (Zig's <c>error.OutOfMemory</c>) when
    /// the raw allocation returns null. The genuine indirect dispatch lives here.</summary>
    public ErrUnion<Slice<T>> Alloc<T>(ulong n, ushort oom) where T : unmanaged
    {
        ulong bytes = n * (ulong)sizeof(T);
        byte* p = Vtable.alloc(Ctx, bytes, AlignOf<T>(), 0);
        return p == null
            ? ErrUnion<Slice<T>>.Err(oom)
            : ErrUnion<Slice<T>>.Ok(new Slice<T>((T*)p, n));
    }

    /// <summary><c>a.free(slice)</c> — free a slice previously returned by
    /// <see cref="Alloc{T}"/>, passing the byte-length <c>[]u8</c> back to the raw free (Zig
    /// allocators take the size at free time).</summary>
    public void Free<T>(Slice<T> s) where T : unmanaged
        => Vtable.free(Ctx, new Slice<byte>((byte*)s.Ptr, s.Len * (ulong)sizeof(T)), AlignOf<T>(), 0);

    /// <summary><c>a.free(slice)</c> of a <c>[]const T</c> (std.StaticStringMap.deinit's
    /// <c>allocator.free(self.len_indexes[0..self.len_indexes_len])</c>): zig's <c>free</c> takes any
    /// slice, const or not, as the memory it gives back.</summary>
    public void Free<T>(ConstSlice<T> s) where T : unmanaged
        => Vtable.free(Ctx, new Slice<byte>((byte*)s.Ptr, s.Len * (ulong)sizeof(T)), AlignOf<T>(), 0);

    /// <summary>The byte alignment dotcc passes for an element type <typeparamref name="T"/>.
    /// Delegates to <see cref="ZigAlloc.AlignOf{T}"/> — the single source of truth shared with the
    /// devirtualized allocator paths — so the vtable and devirt paths request identical alignment.</summary>
    private static Alignment AlignOf<T>() where T : unmanaged => ZigAlloc.AlignOf<T>();

    /// <summary><c>a.create(T)</c> — allocate one <typeparamref name="T"/> through the vtable
    /// (Milestone U). The address is carried back as a <c>nuint</c>: a pointer cannot be the
    /// generic argument of <see cref="ErrUnion{T}"/> (<c>T : unmanaged</c> excludes pointer
    /// types), so <c>Error!*T</c> is represented as <c>ErrUnion&lt;nuint&gt;</c> and the caller
    /// casts the unwrapped value back to <c>T*</c>. Returns <paramref name="oom"/> on failure.</summary>
    public ErrUnion<nuint> Create<T>(ushort oom) where T : unmanaged
    {
        byte* p = Vtable.alloc(Ctx, (ulong)sizeof(T), AlignOf<T>(), 0);
        return p == null ? ErrUnion<nuint>.Err(oom) : ErrUnion<nuint>.Ok((nuint)p);
    }

    /// <summary><c>a.destroy(p)</c> — free a single object previously returned by
    /// <see cref="Create{T}"/>, passing <c>sizeof(T)</c> back as the byte length. A <c>T*</c>
    /// is a legal method PARAMETER even though it cannot be a generic type ARGUMENT.</summary>
    public void Destroy<T>(T* p) where T : unmanaged
        => Vtable.free(Ctx, new Slice<byte>((byte*)p, (ulong)sizeof(T)), AlignOf<T>(), 0);

    /// <summary><c>a.realloc(slice, n)</c> (Milestone U) — grow/shrink through the vtable. The
    /// <see cref="Allocator"/> vtable has only alloc/free, so realloc is EMULATED: allocate a fresh
    /// region, copy the preserved prefix, free the old. Returns the new <see cref="Slice{T}"/> or
    /// <paramref name="oom"/>.</summary>
    public ErrUnion<Slice<T>> Realloc<T>(Slice<T> old, ulong n, ushort oom) where T : unmanaged
    {
        var fresh = Alloc<T>(n, oom);
        if (fresh.IsErr) { return fresh; }
        ulong keep = old.Len < n ? old.Len : n;
        global::System.Buffer.MemoryCopy(old.Ptr, fresh.Value.Ptr, (long)(n * (ulong)sizeof(T)), (long)(keep * (ulong)sizeof(T)));
        Free(old);
        return fresh;
    }

    /// <summary><c>a.resize(slice, n)</c> — attempt an IN-PLACE resize (no move) through the vtable's
    /// <see cref="AllocatorVTable.resize"/> fn, returning whether it succeeded (Zig's <c>bool</c>).
    /// The answer is whatever the concrete runtime allocator gives: an <see cref="FixedBufferAllocator"/>
    /// applies its last-allocation logic (grow the top block if the buffer has room, shrink any block),
    /// while the C heap and arena always report <c>false</c> (they can't grow/shrink in place, so the
    /// caller falls back to a copying realloc). No <c>ret_addr</c> is threaded (0), matching the other
    /// dispatch helpers.</summary>
    public CBool Resize<T>(Slice<T> s, ulong n) where T : unmanaged
        => Vtable.resize(Ctx, new Slice<byte>((byte*)s.Ptr, s.Len * (ulong)sizeof(T)), AlignOf<T>(), n * (ulong)sizeof(T), 0);

    /// <summary><c>a.remap(slice, n)</c> — resize-possibly-moving through the vtable's
    /// <see cref="AllocatorVTable.remap"/> fn. Returns the (possibly relocated) slice of
    /// <paramref name="n"/> elements on success, or <c>null</c> (Zig's <c>?[]T</c>) when the
    /// allocator can't honor it. dotcc's allocators never actually move a block (an FBA remaps in
    /// place; the C heap / arena return null), so a non-null result carries the same pointer with the
    /// new length — but the shape follows real zig, which is free to relocate.</summary>
    public Slice<T>? Remap<T>(Slice<T> s, ulong n) where T : unmanaged
    {
        byte* p = Vtable.remap(Ctx, new Slice<byte>((byte*)s.Ptr, s.Len * (ulong)sizeof(T)), AlignOf<T>(), n * (ulong)sizeof(T), 0);
        return p == null ? null : new Slice<T>((T*)p, n);
    }
}

/// <summary>
/// A bump allocator over a caller-supplied fixed byte buffer — Zig's
/// <c>std.heap.FixedBufferAllocator</c>. The second concrete allocator, so the
/// <see cref="Allocator"/> vtable has something other than the C heap to dispatch to. No heap,
/// fully deterministic: allocation past the buffer end returns null (→ <c>error.OutOfMemory</c>),
/// which makes overflow an observable, repeatable test.
/// </summary>
public unsafe struct FixedBufferAllocator
{
    /// <summary>The backing buffer.</summary>
    public byte* Buffer;

    /// <summary>The buffer's capacity in bytes.</summary>
    public ulong Capacity;

    /// <summary>The bump cursor — bytes handed out so far.</summary>
    public ulong EndIndex;

    /// <summary><c>FixedBufferAllocator.init(buf)</c> — wrap a buffer of
    /// <paramref name="cap"/> bytes at <paramref name="buf"/>.</summary>
    public static FixedBufferAllocator Init(byte* buf, ulong cap)
        => new() { Buffer = buf, Capacity = cap, EndIndex = 0 };
}

/// <summary>The header of one <see cref="ArenaAllocator"/> chunk — a singly-linked node prefixing a
/// run of <see cref="Cap"/> bump-allocatable bytes. The usable space starts a fixed,
/// 16-byte-aligned distance after the header (<c>ZigAlloc.ArenaHeaderBytes</c>), so every handed-out
/// pointer is at least 16-aligned. Public so it can be the type of <see cref="ArenaAllocator"/>'s
/// public <c>Current</c> field (a self-pointer chain has no encapsulation to protect here).</summary>
public unsafe struct ArenaChunk
{
    /// <summary>The previously-allocated chunk (freed before this one at deinit), or null.</summary>
    public ArenaChunk* Prev;

    /// <summary>The usable capacity in bytes (after the aligned header).</summary>
    public nuint Cap;

    /// <summary>Bytes handed out of this chunk so far.</summary>
    public nuint Used;
}

/// <summary>
/// A growing arena over a backing <see cref="Allocator"/> — Zig's <c>std.heap.ArenaAllocator</c>.
/// The third concrete allocator: it bump-allocates within malloc'd chunks (grown on demand from
/// <see cref="Backing"/>) and reclaims EVERYTHING at once in <see cref="Deinit"/> — the headline
/// pairing with <c>defer arena.deinit()</c>. Per-allocation <c>free</c> is a no-op (an arena only
/// frees wholesale). AOT-clean: a raw <see cref="ArenaChunk"/>* chain, no managed collections.
/// </summary>
public unsafe struct ArenaAllocator
{
    /// <summary>The backing allocator the chunks are drawn from (and returned to at deinit).</summary>
    public Allocator Backing;

    /// <summary>The current (newest) chunk — null until the first allocation.</summary>
    public ArenaChunk* Current;

    /// <summary><c>std.heap.ArenaAllocator.init(backing)</c> — wrap a backing allocator. No chunk is
    /// allocated until the first <c>alloc</c>.</summary>
    public static ArenaAllocator Init(Allocator backing)
        => new() { Backing = backing, Current = null };

    /// <summary><c>arena.deinit()</c> — free every chunk back to <see cref="Backing"/> (newest
    /// first) and reset. Idempotent: a second call sees an empty chain.</summary>
    public void Deinit()
    {
        ArenaChunk* ch = Current;
        while (ch != null)
        {
            ArenaChunk* prev = ch->Prev;
            Backing.Vtable.free(Backing.Ctx,
                new Slice<byte>((byte*)ch, (ulong)((nuint)ZigAlloc.ArenaHeaderBytes + ch->Cap)), new Alignment(16), 0);
            ch = prev;
        }
        Current = null;
    }
}

/// <summary>
/// Static entry points for the Zig allocator runtime: the C-heap raw functions (which back the
/// devirtualized default), the <see cref="FixedBufferAllocator"/> raw functions, and the
/// factory helpers the lowering emits (<see cref="CHeap"/>, <see cref="FbaAllocator"/>, and the
/// devirt'd <see cref="AllocCHeap{T}"/> / <see cref="FreeCHeap{T}"/>).
/// </summary>
public static unsafe class ZigAlloc
{
    // Repeated &Method evaluations may produce different managed entry points.
    // Cache each vtable once; allocator instances keep their own context pointer.
    private static readonly AllocatorVTable CHeapVtable = new()
    {
        alloc = &CHeapAlloc, resize = &CHeapResize, remap = &CHeapRemap, free = &CHeapFree
    };

    private static readonly AllocatorVTable FbaVtable = new()
    {
        alloc = &FbaAlloc, resize = &FbaResize, remap = &FbaRemap, free = &FbaFree
    };

    private static readonly AllocatorVTable ArenaVtable = new()
    {
        alloc = &ArenaAlloc, resize = &ArenaResize, remap = &ArenaRemap, free = &ArenaFree
    };

    /// <summary>The byte alignment dotcc requests for an element type <typeparamref name="T"/> — the
    /// largest power of two ≤ <c>min(sizeof(T), 16)</c>. The single source of truth: both the vtable
    /// path (<see cref="Allocator"/>) and the devirtualized allocator sites feed it, so a given
    /// source allocation requests the same alignment either way. .NET has no <c>alignof</c>, so this
    /// size-derived value is an approximation — exact alignment is not modeled (documented in
    /// <see cref="Alignment"/>). It caps at 16, which is why the C heap (≥16-aligned) and the arena
    /// (16-aligned data start) satisfy every request dotcc can generate.</summary>
    internal static Alignment AlignOf<T>() where T : unmanaged
    {
        ulong s = (ulong)sizeof(T);
        ulong a = 1;
        while ((a << 1) <= s && (a << 1) <= 16) { a <<= 1; }
        return new Alignment(a);
    }

    // ---- C heap (the statically-known default) ---------------------------

    /// <summary>Raw C-heap allocation — the vtable's <c>alloc</c> for a materialized default
    /// allocator. <see cref="Libc.malloc"/> takes an <c>int</c>, so a request wider than
    /// <see cref="int.MaxValue"/> is treated as a failure (null).</summary>
    private static byte* CHeapAlloc(void* ctx, ulong len, Alignment alignment, ulong retAddr)
        => len > int.MaxValue ? null : (byte*)Libc.malloc((int)len);

    /// <summary>Raw C-heap resize — always <c>false</c> (malloc can't grow/shrink in place; the
    /// caller falls back to a copying realloc). Part of the 4-fn vtable shape; see
    /// <see cref="AllocatorVTable.resize"/>.</summary>
    private static CBool CHeapResize(void* ctx, Slice<byte> memory, Alignment alignment, ulong newLen, ulong retAddr) => false;

    /// <summary>Raw C-heap remap — always <c>null</c> (no in-place move; the caller copies).</summary>
    private static byte* CHeapRemap(void* ctx, Slice<byte> memory, Alignment alignment, ulong newLen, ulong retAddr) => null;

    /// <summary>Raw C-heap free — the vtable's <c>free</c>. <see cref="Libc.free"/> ignores the
    /// size + alignment, so the <c>[]u8</c> / <c>Alignment</c> are dropped.</summary>
    private static void CHeapFree(void* ctx, Slice<byte> memory, Alignment alignment, ulong retAddr) => Libc.free(memory.Ptr);

    /// <summary>Materialize the C-heap default as a runtime <see cref="Allocator"/> value —
    /// used when the statically-known default is passed to an opaque
    /// <c>std.mem.Allocator</c> sink (a parameter / return), where it must become a real
    /// fat-pointer value. Its vtable still reaches <see cref="Libc.malloc"/>/<see cref="Libc.free"/>.</summary>
    public static Allocator CHeap()
        => new() { Ctx = null, Vtable = CHeapVtable };

    /// <summary>The <b>devirtualized</b> <c>page_allocator.alloc(T, n)</c> — a direct
    /// <see cref="Libc.malloc"/>, no vtable load. Emitted whenever the lowering proves the
    /// allocator is the statically-known C-heap default.</summary>
    public static ErrUnion<Slice<T>> AllocCHeap<T>(ulong n, ushort oom) where T : unmanaged
    {
        ulong bytes = n * (ulong)sizeof(T);
        byte* p = bytes > int.MaxValue ? null : (byte*)Libc.malloc((int)bytes);
        return p == null
            ? ErrUnion<Slice<T>>.Err(oom)
            : ErrUnion<Slice<T>>.Ok(new Slice<T>((T*)p, n));
    }

    /// <summary>The <b>devirtualized</b> <c>page_allocator.free(slice)</c> — a direct
    /// <see cref="Libc.free"/>.</summary>
    public static void FreeCHeap<T>(Slice<T> s) where T : unmanaged => Libc.free(s.Ptr);

    /// <summary><c>a.rawAlloc(len, alignment, ret_addr)</c>: the vtable's byte-level alloc, null on failure
    /// (std.Io.Writer.Allocating grows its buffer this way).</summary>
    public static byte* RawAlloc(Allocator a, ulong len, Alignment alignment, ulong retAddr)
        => a.Vtable.alloc(a.Ctx, len, alignment, retAddr);

    /// <summary><c>a.rawResize(memory, alignment, new_len, ret_addr)</c>: whether the block resized in place.</summary>
    public static CBool RawResize(Allocator a, Slice<byte> memory, Alignment alignment, ulong newLen, ulong retAddr)
        => a.Vtable.resize(a.Ctx, memory, alignment, newLen, retAddr);

    /// <summary><c>a.rawRemap(memory, alignment, new_len, ret_addr)</c>: the possibly-moved block, null when it could not.</summary>
    public static byte* RawRemap(Allocator a, Slice<byte> memory, Alignment alignment, ulong newLen, ulong retAddr)
        => a.Vtable.remap(a.Ctx, memory, alignment, newLen, retAddr);

    /// <summary><c>a.rawFree(memory, alignment, ret_addr)</c>: the vtable's byte-level free.</summary>
    public static void RawFree(Allocator a, Slice<byte> memory, Alignment alignment, ulong retAddr)
        => a.Vtable.free(a.Ctx, memory, alignment, retAddr);

    /// <summary><c>allocator.dupe(T, m)</c>: allocate <c>m.len</c> elements through <paramref name="a"/> and copy
    /// <paramref name="src"/> into them. Returns the copy, or the error code <paramref name="oom"/> when the
    /// allocation fails.</summary>
    public static ErrUnion<Slice<T>> Dupe<T>(Allocator a, ConstSlice<T> src, ushort oom) where T : unmanaged
    {
        var fresh = a.Alloc<T>(src.Len, oom);
        if (!fresh.IsErr && src.Len > 0)
        {
            ulong bytes = src.Len * (ulong)sizeof(T);
            Buffer.MemoryCopy(src.Ptr, fresh.Value.Ptr, bytes, bytes);
        }
        return fresh;
    }

    /// <summary><c>a.dupeSentinel(T, m, s)</c> → <c>Error![:s]T</c>: a copy of <paramref name="src"/> with
    /// <paramref name="sentinel"/> stored one past its end, so the allocation holds <c>len + 1</c> elements and the
    /// returned slice the <c>len</c> before the sentinel (zig's <c>[:s]T</c> layout).</summary>
    public static ErrUnion<Slice<T>> DupeSentinel<T>(Allocator a, ConstSlice<T> src, T sentinel, ushort oom) where T : unmanaged
    {
        var fresh = a.Alloc<T>(src.Len + 1, oom);
        if (fresh.IsErr) { return fresh; }
        if (src.Len > 0)
        {
            ulong bytes = src.Len * (ulong)sizeof(T);
            Buffer.MemoryCopy(src.Ptr, fresh.Value.Ptr, bytes, bytes);
        }
        fresh.Value.Ptr[src.Len] = sentinel;
        return ErrUnion<Slice<T>>.Ok(new Slice<T>(fresh.Value.Ptr, src.Len));
    }

    /// <summary><c>a.allocSentinel(T, n, s)</c> → <c>Error![:s]T</c>: <c>n + 1</c> elements with
    /// <paramref name="sentinel"/> at index <paramref name="n"/>, returned as the <c>n</c>-long slice before it.</summary>
    public static ErrUnion<Slice<T>> AllocSentinel<T>(Allocator a, ulong n, T sentinel, ushort oom) where T : unmanaged
    {
        var fresh = a.Alloc<T>(n + 1, oom);
        if (fresh.IsErr) { return fresh; }
        fresh.Value.Ptr[n] = sentinel;
        return ErrUnion<Slice<T>>.Ok(new Slice<T>(fresh.Value.Ptr, n));
    }

    /// <summary>The <b>devirtualized</b> <c>page_allocator.create(T)</c> — a direct
    /// <see cref="Libc.malloc"/> of <c>sizeof(T)</c> bytes, no vtable. The address is carried as a
    /// <c>nuint</c> (see <see cref="Allocator.Create{T}"/> for why).</summary>
    public static ErrUnion<nuint> CreateCHeap<T>(ushort oom) where T : unmanaged
    {
        byte* p = (byte*)Libc.malloc(sizeof(T));
        return p == null ? ErrUnion<nuint>.Err(oom) : ErrUnion<nuint>.Ok((nuint)p);
    }

    /// <summary>The <b>devirtualized</b> <c>page_allocator.destroy(p)</c> — a direct
    /// <see cref="Libc.free"/>.</summary>
    public static void DestroyCHeap<T>(T* p) where T : unmanaged => Libc.free(p);

    // ---- FixedBufferAllocator (the second allocator) ---------------------

    /// <summary>Raw FBA allocation — align the next pointer up to the requested
    /// <paramref name="alignment"/> (exactly as real zig's <c>alignPointerOffset</c> does: the pad
    /// is charged to the bump cursor), then bump <see cref="FixedBufferAllocator.EndIndex"/>. Returns
    /// null when the aligned request would overflow the buffer (Zig's <c>error.OutOfMemory</c>).</summary>
    private static byte* FbaAlloc(void* ctx, ulong len, Alignment alignment, ulong retAddr)
    {
        var self = (FixedBufferAllocator*)ctx;
        ulong a = alignment.toByteUnits();
        if (a < 1) { a = 1; }
        // Offset needed to align (buffer base + cursor) up to `a`; real zig aligns the POINTER, not
        // just the index, so the buffer's own base address participates.
        nuint cur = (nuint)(self->Buffer + self->EndIndex);
        ulong pad = (ulong)((((cur + (nuint)a - 1) & ~((nuint)a - 1))) - cur);
        ulong adjusted = self->EndIndex + pad;
        ulong end = adjusted + len;
        if (end > self->Capacity) { return null; }
        byte* p = self->Buffer + adjusted;
        self->EndIndex = end;
        return p;
    }

    /// <summary>Raw FBA resize — change a block's length IN PLACE (no move), returning whether it
    /// succeeded, exactly as real zig's <c>FixedBufferAllocator.resize</c>. The LAST allocation can
    /// grow (if the buffer has room) or shrink (rewinding the cursor); any earlier block can only
    /// shrink in place (a grow would collide with the block above it) — a grow of a non-last block
    /// fails, a shrink is a no-op success. Deterministic (no page rounding), which is why resize is
    /// wired for a provable FBA but stays deferred for the C heap / opaque allocators.</summary>
    private static CBool FbaResize(void* ctx, Slice<byte> memory, Alignment alignment, ulong newLen, ulong retAddr)
    {
        var self = (FixedBufferAllocator*)ctx;
        bool isLast = (byte*)memory.Ptr + memory.Len == self->Buffer + self->EndIndex;
        if (!isLast)
        {
            return newLen <= memory.Len;   // a non-last block: shrink is a no-op success, grow fails
        }
        if (newLen <= memory.Len)
        {
            self->EndIndex -= memory.Len - newLen;   // shrink the last block: rewind the cursor
            return true;
        }
        ulong add = newLen - memory.Len;
        if (self->EndIndex + add > self->Capacity) { return false; }   // grow the last block if room
        self->EndIndex += add;
        return true;
    }

    /// <summary>Raw FBA remap — resize-possibly-moving; returns the (unchanged) pointer on success or
    /// null. An FBA never moves a block, so remap IS resize: real zig's
    /// <c>return if (resize(…)) memory.ptr else null;</c>.</summary>
    private static byte* FbaRemap(void* ctx, Slice<byte> memory, Alignment alignment, ulong newLen, ulong retAddr)
        => FbaResize(ctx, memory, alignment, newLen, retAddr) != 0 ? (byte*)memory.Ptr : null;

    /// <summary>Raw FBA free — reclaim the space iff this is the LAST allocation (real zig's
    /// <c>isLastAllocation</c> trick: the freed region ends exactly at the bump cursor, so the cursor
    /// rewinds by its length). Freeing any earlier region is a no-op — a bump allocator can only pop
    /// the top. The alignment pad ahead of the region is intentionally not reclaimed (matches zig).</summary>
    private static void FbaFree(void* ctx, Slice<byte> memory, Alignment alignment, ulong retAddr)
    {
        var self = (FixedBufferAllocator*)ctx;
        if ((byte*)memory.Ptr + memory.Len == self->Buffer + self->EndIndex)
        {
            self->EndIndex -= memory.Len;
        }
    }

    /// <summary><c>fba.allocator()</c> — produce an <see cref="Allocator"/> fat pointer whose
    /// context is the FBA and whose vtable bumps it. The caller passes <c>&amp;fba</c>, so the
    /// returned allocator is valid only while that <see cref="FixedBufferAllocator"/> local is
    /// alive (the same stack-lifetime rule as Zig).</summary>
    public static Allocator FbaAllocator(FixedBufferAllocator* self)
        => new() { Ctx = self, Vtable = FbaVtable };

    /// <summary>The <b>FBA-site-devirtualized</b> <c>a.alloc(T, n)</c> (Milestone U) — a direct FBA
    /// bump with no vtable load, emitted when the lowering proves <c>a</c> is a particular
    /// <c>fba.allocator()</c> result. The <c>&amp;fba</c> context is passed explicitly.</summary>
    public static ErrUnion<Slice<T>> AllocFba<T>(FixedBufferAllocator* self, ulong n, ushort oom) where T : unmanaged
    {
        ulong bytes = n * (ulong)sizeof(T);
        byte* p = FbaAlloc(self, bytes, AlignOf<T>(), 0);
        return p == null
            ? ErrUnion<Slice<T>>.Err(oom)
            : ErrUnion<Slice<T>>.Ok(new Slice<T>((T*)p, n));
    }

    /// <summary>The FBA-site-devirtualized <c>a.free(slice)</c> — reclaims the space iff it is the
    /// last allocation, mirroring <see cref="FbaFree"/> (real zig's <c>isLastAllocation</c>).</summary>
    public static void FreeFba<T>(FixedBufferAllocator* self, Slice<T> s) where T : unmanaged
    {
        ulong bytes = s.Len * (ulong)sizeof(T);
        if ((byte*)s.Ptr + bytes == self->Buffer + self->EndIndex)
        {
            self->EndIndex -= bytes;
        }
    }

    /// <summary>The FBA-site-devirtualized <c>a.create(T)</c> (Milestone U) — a direct FBA bump of
    /// <c>sizeof(T)</c> bytes; the address rides as a <c>nuint</c> (see <see cref="Allocator.Create{T}"/>).</summary>
    public static ErrUnion<nuint> CreateFba<T>(FixedBufferAllocator* self, ushort oom) where T : unmanaged
    {
        byte* p = FbaAlloc(self, (ulong)sizeof(T), AlignOf<T>(), 0);
        return p == null ? ErrUnion<nuint>.Err(oom) : ErrUnion<nuint>.Ok((nuint)p);
    }

    /// <summary>The FBA-site-devirtualized <c>a.destroy(p)</c> — reclaims the object iff it is the
    /// last allocation, mirroring <see cref="FreeFba{T}"/>.</summary>
    public static void DestroyFba<T>(FixedBufferAllocator* self, T* p) where T : unmanaged
    {
        ulong bytes = (ulong)sizeof(T);
        if ((byte*)p + bytes == self->Buffer + self->EndIndex)
        {
            self->EndIndex -= bytes;
        }
    }

    // ---- realloc (Milestone U) -------------------------------------------

    /// <summary>The DEVIRTUALIZED C-heap <c>a.realloc(slice, n)</c> — a direct
    /// <see cref="Libc.realloc"/> (which preserves contents up to the smaller of old/new). Returns a
    /// new <see cref="Slice{T}"/> of <paramref name="n"/> elements, or <paramref name="oom"/> on
    /// failure (incl. a byte count past <see cref="int.MaxValue"/>, since <see cref="Libc.realloc"/>
    /// takes an <c>int</c>).</summary>
    public static ErrUnion<Slice<T>> ReallocCHeap<T>(Slice<T> old, ulong n, ushort oom) where T : unmanaged
    {
        nuint bytes = (nuint)n * (nuint)sizeof(T);
        if (bytes > int.MaxValue) { return ErrUnion<Slice<T>>.Err(oom); }
        void* p = Libc.realloc(old.Ptr, (int)bytes);
        return p == null
            ? ErrUnion<Slice<T>>.Err(oom)
            : ErrUnion<Slice<T>>.Ok(new Slice<T>((T*)p, n));
    }

    /// <summary>The FBA-site-devirtualized <c>a.realloc(slice, n)</c> — EMULATED (an FBA has no
    /// in-place grow): bump a fresh region and copy the preserved prefix. The old region is left in
    /// the buffer (an FBA reclaims only by reset), matching <see cref="FbaFree"/>.</summary>
    public static ErrUnion<Slice<T>> ReallocFba<T>(FixedBufferAllocator* self, Slice<T> old, ulong n, ushort oom) where T : unmanaged
    {
        ulong bytes = n * (ulong)sizeof(T);
        byte* p = FbaAlloc(self, bytes, AlignOf<T>(), 0);
        if (p == null) { return ErrUnion<Slice<T>>.Err(oom); }
        ulong keep = old.Len < n ? old.Len : n;
        global::System.Buffer.MemoryCopy(old.Ptr, p, (long)bytes, (long)(keep * (ulong)sizeof(T)));
        return ErrUnion<Slice<T>>.Ok(new Slice<T>((T*)p, n));
    }

    /// <summary>The FBA-site-devirtualized <c>a.resize(slice, n)</c> — a direct <see cref="FbaResize"/>
    /// over the <c>&amp;fba</c> context; returns whether the block was resized in place (Zig's
    /// <c>bool</c>). No allocation, no move: the caller keeps using <c>slice.ptr[0..n]</c> on success.</summary>
    public static CBool ResizeFba<T>(FixedBufferAllocator* self, Slice<T> s, ulong n) where T : unmanaged
        => FbaResize(self, new Slice<byte>((byte*)s.Ptr, s.Len * (ulong)sizeof(T)), AlignOf<T>(), n * (ulong)sizeof(T), 0);

    /// <summary>The FBA-site-devirtualized <c>a.remap(slice, n)</c> — a direct <see cref="FbaRemap"/>.
    /// Returns the resized slice (same pointer — an FBA never moves) on success, or <c>null</c> (Zig's
    /// <c>?[]T</c> none) when the in-place resize can't be honored.</summary>
    public static Slice<T>? RemapFba<T>(FixedBufferAllocator* self, Slice<T> s, ulong n) where T : unmanaged
    {
        byte* p = FbaRemap(self, new Slice<byte>((byte*)s.Ptr, s.Len * (ulong)sizeof(T)), AlignOf<T>(), n * (ulong)sizeof(T), 0);
        return p == null ? null : new Slice<T>((T*)p, n);
    }

    // ---- ArenaAllocator (the third allocator, Milestone U) ---------------

    /// <summary>The 16-byte-aligned distance from a chunk's start to its usable space.
    /// <see cref="ArenaChunk"/> is 24 bytes on 64-bit; rounding to 32 keeps the data start
    /// 16-aligned (malloc returns ≥16-aligned), so every handed-out pointer is 16-aligned.</summary>
    internal const int ArenaHeaderBytes = 32;

    /// <summary>Raw arena allocation — bump within the current chunk, growing when the request doesn't fit the way zig's
    /// ArenaAllocator does: first the current chunk IN PLACE through the backing allocator's resize (a FixedBufferAllocator
    /// grows its last allocation), else a new chunk sized from what is needed, <c>alignForward(big + big / 2, 2)</c> with
    /// <c>big = previous chunk + header + request + 16</c>. A fixed 4 KiB first chunk had failed with OutOfMemory over a
    /// 1 KiB buffer zig's arena fits in. Requests are 16-byte-aligned so mixed-type allocations stay aligned. Returns null
    /// only when the backing allocator is exhausted.</summary>
    private static byte* ArenaAlloc(void* ctx, ulong len, Alignment alignment, ulong retAddr)
    {
        var self = (ArenaAllocator*)ctx;
        nuint need = ((nuint)len + 15) & ~(nuint)15;   // round up to a 16-byte multiple
        if (self->Current is var current && current != null && current->Used + need > current->Cap)
        {
            nuint grown = current->Used + need;
            var held = new Slice<byte>((byte*)current, (ulong)((nuint)ArenaHeaderBytes + current->Cap));
            if ((int)self->Backing.Vtable.resize(self->Backing.Ctx, held, alignment, (ulong)((nuint)ArenaHeaderBytes + grown), 0) != 0)
            {
                current->Cap = grown;
            }
        }
        if (self->Current == null || self->Current->Used + need > self->Current->Cap)
        {
            nuint previous = self->Current == null ? 0 : (nuint)ArenaHeaderBytes + self->Current->Cap;
            nuint big = previous + (nuint)ArenaHeaderBytes + need + 16;
            nuint total = (big + big / 2 + 1) & ~(nuint)1;
            byte* raw = self->Backing.Vtable.alloc(self->Backing.Ctx, (ulong)total, alignment, 0);
            if (raw == null) { return null; }
            var ch = (ArenaChunk*)raw;
            ch->Prev = self->Current;
            ch->Cap = total - (nuint)ArenaHeaderBytes;
            ch->Used = 0;
            self->Current = ch;
        }
        byte* p = (byte*)self->Current + ArenaHeaderBytes + self->Current->Used;
        self->Current->Used += need;
        return p;
    }

    /// <summary>Raw arena resize/remap — never succeeds in place (false / null); part of the 4-fn
    /// vtable shape (see <see cref="AllocatorVTable.resize"/>).</summary>
    private static CBool ArenaResize(void* ctx, Slice<byte> memory, Alignment alignment, ulong newLen, ulong retAddr) => false;
    private static byte* ArenaRemap(void* ctx, Slice<byte> memory, Alignment alignment, ulong newLen, ulong retAddr) => null;

    /// <summary>Raw arena free — a no-op (an arena reclaims wholesale in <see cref="ArenaAllocator.Deinit"/>).</summary>
    private static void ArenaFree(void* ctx, Slice<byte> memory, Alignment alignment, ulong retAddr) { }

    /// <summary><c>arena.allocator()</c> — produce an <see cref="Allocator"/> fat pointer whose
    /// context is the arena and whose vtable bump-allocates it. Valid only while the
    /// <see cref="ArenaAllocator"/> local is alive (the same stack-lifetime rule as Zig).</summary>
    public static Allocator ArenaToAllocator(ArenaAllocator* self)
        => new() { Ctx = self, Vtable = ArenaVtable };

    /// <summary><c>arena.deinit()</c> — free the whole chunk chain. A static wrapper over
    /// <see cref="ArenaAllocator.Deinit"/> (called by-ref on the local, like <see cref="ArenaToAllocator"/>).</summary>
    public static void ArenaDeinit(ArenaAllocator* self) => self->Deinit();

    // ---- array-by-value return (the Milestone K cut, made sound) ---------

    /// <summary>Copy an <paramref name="n"/>-element array at <paramref name="src"/> into a fresh
    /// heap-owned buffer and return the pointer — the sound lowering of a Zig <c>[N]T</c> by-value
    /// return. The callee's array local is a <c>stackalloc</c> that dies with its frame, but Zig
    /// arrays are VALUE types, so the caller must receive a copy that outlives the call (returning
    /// the stackalloc pointer directly would be a dangling pointer). V1: the buffer is NOT freed
    /// (leaked — sound values, unfreed); a caller-allocated result pointer (sret) would avoid the
    /// leak but rewrites the call ABI. BCL names are fully qualified because the runtime-splice
    /// strips <c>using</c> directives when this file is embedded into an emitted program.</summary>
    public static T* CopyArrayResult<T>(T* src, int n) where T : unmanaged
    {
        nuint bytes = (nuint)n * (nuint)sizeof(T);
        return (T*)CopyArrayResultBytes(src, bytes);
    }

    /// <summary>The same owned byte copy for compiler-known pointer-free value
    /// storage that C# excludes from an unmanaged generic argument (Nullable).</summary>
    public static void* CopyArrayResultBytes(void* src, nuint bytes)
    {
        var dst = global::System.Runtime.InteropServices.NativeMemory.Alloc(bytes);
        global::System.Buffer.MemoryCopy(src, dst, (long)bytes, (long)bytes);
        return dst;
    }
}


#nullable restore
// ---- ZigBitcastWidth.cs ----
#nullable enable
/// <summary>Exact logical-bit transport. Runtime evidence currently covers little-endian hosts.</summary>
internal static unsafe class ZigBitcastWidth
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static UInt128 Mask(int bits) => bits == 128 ? UInt128.MaxValue : ((UInt128)1 << bits) - 1;
    private static void CheckWidth(int bits)
    {
        if (!BitConverter.IsLittleEndian)
            throw new PlatformNotSupportedException("Zig logical bitcast transport has no big-endian runtime witness");
        if (bits is < 1 or > 128) throw new ArgumentOutOfRangeException(nameof(bits));
    }
    public static TTarget Scalar<TSource, TTarget>(TSource value, int bits, bool signed)
        where TSource : unmanaged where TTarget : unmanaged
    {
        CheckWidth(bits);
        var bytes = (bits + 7) / 8;
        if (bytes > sizeof(TSource)) throw new ArgumentException("Zig bitcast source storage is too small");
        UInt128 packed = 0;
        var source = (byte*)&value;
        for (var b = 0; b < bytes; b++) packed |= (UInt128)source[b] << (8 * b);
        return Result<TTarget>(packed, bits, signed);
    }
    public static TTarget Array<TTarget>(void* source, int count, int elementBits, int stride, int bits, bool signed)
        where TTarget : unmanaged
    {
        CheckWidth(bits);
        if (count <= 0 || elementBits is < 1 or > 128 || (long)count * elementBits != bits || stride < (elementBits + 7) / 8)
            throw new ArgumentException("Invalid Zig bitcast array layout");
        UInt128 packed = 0;
        var bytes = (elementBits + 7) / 8;
        var mask = Mask(elementBits);
        for (var i = 0; i < count; i++)
        {
            UInt128 element = 0;
            var lane = (byte*)source + (nuint)i * (nuint)stride;
            // Read exactly the logical bytes at each physical stride, including
            // a three-byte buffer ending immediately before an inaccessible page.
            for (var b = 0; b < bytes; b++) element |= (UInt128)lane[b] << (8 * b);
            packed |= (element & mask) << (i * elementBits);
        }
        return Result<TTarget>(packed, bits, signed);
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private static TTarget Result<TTarget>(UInt128 packed, int bits, bool signed) where TTarget : unmanaged
    {
        if (sizeof(TTarget) > 16 || sizeof(TTarget) * 8 < bits) throw new ArgumentException("Zig bitcast target storage is unsupported");
        var mask = Mask(bits);
        packed &= mask;
        if (signed && (packed & ((UInt128)1 << (bits - 1))) != 0) packed |= ~mask;
        TTarget result = default;
        var dest = (byte*)&result;
        for (var b = 0; b < sizeof(TTarget); b++) dest[b] = (byte)(packed >> (8 * b));
        return result;
    }
}


