/// <summary>
/// The runtime backing for the Zig front-end's curated <c>std.ArrayList(T)</c> (wall-plan W0) —
/// the modern UNMANAGED array list (zig 0.15+ re-pointed <c>std.ArrayList</c> at the unmanaged
/// variant: no stored allocator, every growing call takes one explicitly). Auto-spliced into
/// every emitted program (the <c>DotCC.Libc/*.cs</c> <c>&lt;EmbeddedResource&gt;</c> glob) and
/// compiled into <c>DotCC.Libc.dll</c> for the unit tests, exactly like <see cref="Slice{T}"/> /
/// <see cref="ZigAlloc"/>.
/// </summary>
/// <remarks>
/// <para>
/// This is a CURATED runtime type, not a transpilation of zig's <c>array_list.zig</c> (which is
/// comptime-soaked): dotcc authors the body, so an open C# generic works — the same reasoning as
/// <see cref="Slice{T}"/>. The lowering resolves the type <c>std.ArrayList(i32)</c> to
/// <c>ZigList&lt;int&gt;</c> and routes the curated member set here; an unmodeled member is a
/// clear error at the use site.
/// </para>
/// <para>
/// Zig's <c>.empty</c> decl literal is exactly <c>default</c>: a null pointer with zero
/// length/capacity (the first growing call allocates). Methods that grow return <c>!void</c>
/// (<c>ErrUnion&lt;Unit&gt;</c>, <c>error.OutOfMemory</c> on an exhausted allocator) so
/// <c>try list.append(alloc, v)</c> composes with the existing error-union machinery. Mutating
/// methods are INSTANCE methods called on an lvalue receiver — a C# struct method mutates the
/// receiver variable in place, matching zig's <c>*Self</c> methods on an addressable list.
/// </para>
/// <para>
/// Mirrors <see cref="Slice{T}"/>'s representation choices: the data pointer is stored as
/// <see cref="nint"/> so the type needs no type-level <c>unsafe</c> (only the members that
/// touch elements are <c>unsafe</c>), and the length/capacity are <c>ulong</c> (Zig's
/// <c>usize</c> on dotcc's LP64 target).
/// </para>
/// </remarks>
public struct ZigList<T> where T : unmanaged
{
    private nint _ptr;

    /// <summary>The element count (zig <c>list.items.len</c>).</summary>
    public ulong Len;

    /// <summary>The allocated capacity in elements (zig <c>list.capacity</c>).</summary>
    public ulong Cap;

    /// <summary>The data pointer (null until the first growing call).</summary>
    public unsafe T* Ptr => (T*)_ptr;

    /// <summary>Zig's <c>list.items</c> — the occupied prefix as a mutable slice, so
    /// <c>list.items[i]</c> / <c>list.items.len</c> ride the existing slice lowering.</summary>
    public unsafe Slice<T> Items => new((T*)_ptr, Len);

    /// <summary>zig's <c>std.atomic.cache_line</c> for the host: 128 bytes on x86_64 and aarch64 (a pair of prefetched
    /// 64-byte lines), 64 elsewhere. It sets the first allocation's size.</summary>
    private static ulong CacheLine =>
        System.Runtime.InteropServices.RuntimeInformation.ProcessArchitecture
            is System.Runtime.InteropServices.Architecture.X64 or System.Runtime.InteropServices.Architecture.Arm64
            ? 128UL : 64UL;

    /// <summary>zig's <c>growCapacity(minimum)</c>: <c>minimum +| (minimum / 2 + init_capacity)</c>, with
    /// <c>init_capacity = @max(1, cache_line / @sizeOf(T))</c>. The capacity a list grows to is observable, through the
    /// point where a bounded allocator (a FixedBufferAllocator) runs out (task #145), so it follows zig exactly.</summary>
    private static unsafe ulong GrowCapacity(ulong minimum)
    {
        ulong init = System.Math.Max(1UL, CacheLine / (ulong)sizeof(T));
        ulong add = minimum / 2 + init;
        return ulong.MaxValue - minimum < add ? ulong.MaxValue : minimum + add;
    }

    /// <summary>zig's <c>ensureTotalCapacityPrecise</c>: exactly <paramref name="n"/> elements. It first tries to
    /// <c>remap</c> the allocation in place (a non-empty one; zig's remap of an empty slice is null), else allocates
    /// afresh, copies the occupied prefix and frees the old block.</summary>
    private unsafe ErrUnion<Unit> EnsureTotalCapacityPrecise(Allocator a, ulong n, ushort oom)
    {
        if (Cap >= n) { return ErrUnion<Unit>.Ok(default); }
        if (Cap != 0 && a.Remap(new Slice<T>((T*)_ptr, Cap), n) is { } remapped)
        {
            _ptr = (nint)remapped.Ptr;
            Cap = remapped.Len;
            return ErrUnion<Unit>.Ok(default);
        }
        var fresh = a.Alloc<T>(n, oom);
        if (fresh.IsErr) { return ErrUnion<Unit>.Err(fresh.Code); }
        long bytes = (long)(Len * (ulong)sizeof(T));
        if (Len != 0) { System.Buffer.MemoryCopy((T*)_ptr, fresh.Value.Ptr, bytes, bytes); }
        if (Cap != 0) { a.Free(new Slice<T>((T*)_ptr, Cap)); }
        _ptr = (nint)fresh.Value.Ptr;
        Cap = n;
        return ErrUnion<Unit>.Ok(default);
    }

    /// <summary>zig's <c>ensureTotalCapacity</c>: nothing when <paramref name="need"/> already fits, else the precise
    /// growth to <see cref="GrowCapacity"/>(<paramref name="need"/>).</summary>
    private ErrUnion<Unit> EnsureCap(Allocator a, ulong need, ushort oom)
        => Cap >= need ? ErrUnion<Unit>.Ok(default) : EnsureTotalCapacityPrecise(a, GrowCapacity(need), oom);

    /// <summary>zig's <c>addManyAt(index, count)</c>, behind <c>insert</c> / <c>insertSlice</c>: room for
    /// <paramref name="count"/> elements at <paramref name="index"/>, the tail moved up. Past capacity it grows to
    /// <see cref="GrowCapacity"/>(new length), by an in-place remap or else a fresh block the head and tail are copied
    /// around (no copy of the old capacity), the old block then freed.</summary>
    private unsafe ErrUnion<Unit> AddManyAt(Allocator a, ulong index, ulong count, ushort oom)
    {
        if (ulong.MaxValue - Len < count) { return ErrUnion<Unit>.Err(oom); }
        ulong newLen = Len + count;
        long tailBytes = (long)((Len - index) * (ulong)sizeof(T));
        if (Cap < newLen)
        {
            ulong newCap = GrowCapacity(newLen);
            if (Cap != 0 && a.Remap(new Slice<T>((T*)_ptr, Cap), newCap) is { } remapped)
            {
                _ptr = (nint)remapped.Ptr;
                Cap = remapped.Len;
            }
            else
            {
                var fresh = a.Alloc<T>(newCap, oom);
                if (fresh.IsErr) { return ErrUnion<Unit>.Err(fresh.Code); }
                var q = fresh.Value.Ptr;
                long headBytes = (long)(index * (ulong)sizeof(T));
                if (index != 0) { System.Buffer.MemoryCopy((T*)_ptr, q, headBytes, headBytes); }
                if (tailBytes != 0) { System.Buffer.MemoryCopy((T*)_ptr + index, q + index + count, tailBytes, tailBytes); }
                if (Cap != 0) { a.Free(new Slice<T>((T*)_ptr, Cap)); }
                _ptr = (nint)q;
                Cap = newCap;
                Len = newLen;
                return ErrUnion<Unit>.Ok(default);
            }
        }
        var p = (T*)_ptr;
        if (tailBytes != 0) { System.Buffer.MemoryCopy(p + index, p + index + count, tailBytes, tailBytes); }
        Len = newLen;
        return ErrUnion<Unit>.Ok(default);
    }

    /// <summary>zig <c>list.append(alloc, item)</c> — append one element, growing as needed.
    /// Returns <c>!void</c>: <c>error.OutOfMemory</c> (<paramref name="oom"/>) when the
    /// allocator is exhausted.</summary>
    public unsafe ErrUnion<Unit> Append(Allocator a, T item, ushort oom)
    {
        var ok = EnsureCap(a, Len + 1, oom);
        if (ok.IsErr) { return ok; }
        ((T*)_ptr)[Len] = item;
        Len += 1;
        return ErrUnion<Unit>.Ok(default);
    }

    /// <summary>zig <c>list.appendSlice(alloc, s)</c> — append every element of a slice.
    /// Takes <see cref="ConstSlice{T}"/> (a mutable <see cref="Slice{T}"/> coerces implicitly,
    /// the same <c>[]T</c> → <c>[]const T</c> rule as zig).</summary>
    public unsafe ErrUnion<Unit> AppendSlice(Allocator a, ConstSlice<T> s, ushort oom)
    {
        var ok = EnsureUnusedCapacity(a, s.Len, oom);
        if (ok.IsErr) { return ok; }
        long bytes = (long)(s.Len * (ulong)sizeof(T));
        global::System.Buffer.MemoryCopy(s.Ptr, (T*)_ptr + Len, bytes, bytes);
        Len += s.Len;
        return ErrUnion<Unit>.Ok(default);
    }

    /// <summary>zig <c>list.pop()</c> — remove and return the last element, or <c>null</c> when
    /// the list is empty (zig 0.15+ changed pop's return to <c>?T</c>).</summary>
    public unsafe T? Pop()
    {
        if (Len == 0) { return null; }
        Len -= 1;
        return ((T*)_ptr)[Len];
    }

    /// <summary>zig <c>list.clearRetainingCapacity()</c> — drop the elements, keep the store.</summary>
    public void ClearRetainingCapacity() => Len = 0;

    /// <summary>zig <c>list.insert(alloc, i, item)</c> — insert at <paramref name="i"/>, shifting the tail up by one.</summary>
    public unsafe ErrUnion<Unit> Insert(Allocator a, ulong i, T item, ushort oom)
    {
        if (i > Len) { throw new System.IndexOutOfRangeException("zig ArrayList.insert: index out of bounds"); }
        var ok = AddManyAt(a, i, 1, oom);
        if (ok.IsErr) { return ok; }
        ((T*)_ptr)[i] = item;
        return ErrUnion<Unit>.Ok(default);
    }

    /// <summary>zig <c>list.insertSlice(alloc, i, s)</c> — insert every element of <paramref name="s"/> at
    /// <paramref name="i"/>, shifting the tail up by <c>s.len</c>. Like zig, the slice must not alias the list.</summary>
    public unsafe ErrUnion<Unit> InsertSlice(Allocator a, ulong i, ConstSlice<T> s, ushort oom)
    {
        if (i > Len) { throw new System.IndexOutOfRangeException("zig ArrayList.insertSlice: index out of bounds"); }
        var ok = AddManyAt(a, i, s.Len, oom);
        if (ok.IsErr) { return ok; }
        long bytes = (long)(s.Len * (ulong)sizeof(T));
        System.Buffer.MemoryCopy(s.Ptr, (T*)_ptr + i, bytes, bytes);
        return ErrUnion<Unit>.Ok(default);
    }

    /// <summary>zig <c>list.orderedRemove(i)</c> — remove and return element <paramref name="i"/>, shifting the tail down.</summary>
    public unsafe T OrderedRemove(ulong i)
    {
        if (i >= Len) { throw new System.IndexOutOfRangeException("zig ArrayList.orderedRemove: index out of bounds"); }
        var p = (T*)_ptr;
        var removed = p[i];
        long bytes = (long)((Len - i - 1) * (ulong)sizeof(T));
        System.Buffer.MemoryCopy(p + i + 1, p + i, bytes, bytes);
        Len -= 1;
        return removed;
    }

    /// <summary>zig <c>list.appendNTimes(alloc, value, n)</c> — append <paramref name="n"/> copies of
    /// <paramref name="value"/>. Grows as zig's <c>resize</c> does (<c>ensureTotalCapacity</c> of the new length).</summary>
    public unsafe ErrUnion<Unit> AppendNTimes(Allocator a, T value, ulong n, ushort oom)
    {
        if (ulong.MaxValue - Len < n) { return ErrUnion<Unit>.Err(oom); }
        var ok = EnsureCap(a, Len + n, oom);
        if (ok.IsErr) { return ok; }
        AppendNTimesAssumeCapacity(value, n);
        return ErrUnion<Unit>.Ok(default);
    }

    /// <summary>zig <c>list.appendNTimesAssumeCapacity(value, n)</c> — the same without growing; the capacity must hold them.</summary>
    public unsafe void AppendNTimesAssumeCapacity(T value, ulong n)
    {
        if (Cap - Len < n) { throw new System.InvalidOperationException("zig ArrayList.appendNTimesAssumeCapacity: capacity exceeded"); }
        var p = (T*)_ptr + Len;
        for (ulong k = 0; k < n; k++) { p[k] = value; }
        Len += n;
    }

    /// <summary>zig <c>list.replaceRange(alloc, start, len, new_items)</c> — replace the <paramref name="len"/> elements
    /// at <paramref name="start"/> by <paramref name="newItems"/>, growing to the new length first when it is longer.</summary>
    public unsafe ErrUnion<Unit> ReplaceRange(Allocator a, ulong start, ulong len, ConstSlice<T> newItems, ushort oom)
    {
        var ok = EnsureCap(a, Len - len + newItems.Len, oom);
        if (ok.IsErr) { return ok; }
        ReplaceRangeAssumeCapacity(start, len, newItems);
        return ErrUnion<Unit>.Ok(default);
    }

    /// <summary>zig <c>list.replaceRangeAssumeCapacity(start, len, new_items)</c> — the tail after the replaced range moves
    /// to follow <paramref name="newItems"/>, and the length changes by their difference; the capacity must hold it.</summary>
    public unsafe void ReplaceRangeAssumeCapacity(ulong start, ulong len, ConstSlice<T> newItems)
    {
        if (start + len > Len) { throw new System.IndexOutOfRangeException("zig ArrayList.replaceRange: range out of bounds"); }
        ulong newLen = Len - len + newItems.Len;
        if (newLen > Cap) { throw new System.InvalidOperationException("zig ArrayList.replaceRangeAssumeCapacity: capacity exceeded"); }
        var p = (T*)_ptr;
        long tailBytes = (long)((Len - start - len) * (ulong)sizeof(T));
        if (tailBytes != 0) { System.Buffer.MemoryCopy(p + start + len, p + start + newItems.Len, tailBytes, tailBytes); }
        long newBytes = (long)(newItems.Len * (ulong)sizeof(T));
        if (newBytes != 0) { System.Buffer.MemoryCopy(newItems.Ptr, p + start, newBytes, newBytes); }
        Len = newLen;
    }

    /// <summary>zig <c>list.swapRemove(i)</c> — remove and return element <paramref name="i"/>, moving the last one into its place.</summary>
    public unsafe T SwapRemove(ulong i)
    {
        if (i >= Len) { throw new System.IndexOutOfRangeException("zig ArrayList.swapRemove: index out of bounds"); }
        var p = (T*)_ptr;
        var removed = p[i];
        p[i] = p[Len - 1];
        Len -= 1;
        return removed;
    }

    /// <summary>zig <c>list.getLast()</c> — the last element, or <c>null</c> when the list is empty (zig 0.17-dev returns
    /// <c>?T</c>).</summary>
    public unsafe T? GetLast() => Len == 0 ? null : ((T*)_ptr)[Len - 1];

    /// <summary>zig <c>list.ensureTotalCapacity(alloc, n)</c> — capacity for at least <paramref name="n"/> elements.</summary>
    public ErrUnion<Unit> EnsureTotalCapacity(Allocator a, ulong n, ushort oom) => EnsureCap(a, n, oom);

    /// <summary>zig <c>list.ensureUnusedCapacity(alloc, n)</c> — room for <paramref name="n"/> more elements.</summary>
    public ErrUnion<Unit> EnsureUnusedCapacity(Allocator a, ulong n, ushort oom)
        => ulong.MaxValue - Len < n ? ErrUnion<Unit>.Err(oom) : EnsureCap(a, Len + n, oom);

    /// <summary>zig <c>list.appendAssumeCapacity(item)</c> — append into capacity reserved earlier.</summary>
    public unsafe void AppendAssumeCapacity(T item)
    {
        if (Len >= Cap) { throw new System.InvalidOperationException("zig ArrayList.appendAssumeCapacity: no capacity left"); }
        ((T*)_ptr)[Len] = item;
        Len += 1;
    }

    /// <summary>zig <c>list.shrinkRetainingCapacity(n)</c> — keep the first <paramref name="n"/> elements.</summary>
    public void ShrinkRetainingCapacity(ulong n)
    {
        if (n > Len) { throw new System.IndexOutOfRangeException("zig ArrayList.shrinkRetainingCapacity: new length exceeds the old"); }
        Len = n;
    }

    /// <summary>zig <c>list.deinit(alloc)</c> — return the backing store to the allocator and
    /// reset to <c>.empty</c>. Idempotent (a second call sees a null pointer), mirroring
    /// <see cref="ArenaAllocator.Deinit"/>.</summary>
    public unsafe void Deinit(Allocator a)
    {
        if (_ptr != 0) { a.Free(new Slice<T>((T*)_ptr, Cap)); }
        _ptr = 0;
        Len = 0;
        Cap = 0;
    }
}


#nullable restore
// ---- ZigMath.cs ----
#nullable enable



/// <summary>
/// The runtime backing for the Zig front-end's SATURATING arithmetic operators
/// (<c>+| -| *|</c> and their compound forms <c>+|= -|= *|=</c>; Milestone P, part 2), the
/// integer math builtins (<c>@min</c>/<c>@max</c>/<c>@rem</c>/<c>@divTrunc</c>/<c>@mod</c>/
/// <c>@divFloor</c>/<c>@popCount</c>/<c>@clz</c>/<c>@ctz</c>/<c>@byteSwap</c>/<c>@abs</c>), and the
/// overflow-detecting builtins (<c>@addWithOverflow</c>/<c>@subWithOverflow</c>/<c>@mulWithOverflow</c>/
/// <c>@shlWithOverflow</c>; road-to-zig-std B3). Auto-spliced into every emitted program (the <c>DotCC.Libc/*.cs</c>
/// <c>&lt;EmbeddedResource&gt;</c> glob) and compiled into <c>DotCC.Libc.dll</c> for the unit
/// tests, exactly like <see cref="Slice{T}"/> / <see cref="ErrUnion{T}"/> / the allocator types.
/// </summary>
/// <remarks>
/// <para>
/// Zig's <c>a +| b</c> clamps the true mathematical result to the operand type's range rather
/// than wrapping (<c>+%</c>) or trapping (plain <c>+</c>): <c>u8: 200 +| 100 == 255</c>,
/// <c>i8: 100 +| 100 == 127</c>, <c>i8: -100 -| 100 == -128</c>. The wrapping sibling lives in
/// the emitter (a truncating cast in the project's unchecked context); saturation needs a clamp,
/// which has no native C# operator, so it routes here.
/// </para>
/// <para>
/// <b>Design — exact-in-128-bit, then clamp.</b> Every integer type the Zig front-end produces is
/// at most 64-bit (<c>usize</c>→<c>ulong</c>; arbitrary <c>iN</c>/<c>uN</c> are unsupported), so
/// the true result of an add/sub/mul of two such operands always fits in a 128-bit accumulator
/// (the largest case, <c>ulong * ulong</c>, is below <see cref="System.UInt128"/>'s max). So each
/// operation widens both operands to <see cref="System.Int128"/> / <see cref="System.UInt128"/>,
/// performs the EXACT operation there (no overflow, no exceptions, no division-trap edge cases),
/// and clamps to <c>[T.MinValue, T.MaxValue]</c> before truncating back to <typeparamref name="T"/>.
/// This is branch-light and exception-free — unlike a <c>checked(…)</c>/<c>catch</c> form, the
/// saturating path costs nothing extra when no saturation occurs.
/// </para>
/// <para>
/// Signedness is read from <c>T.IsNegative(T.MinValue)</c> (true for a signed <typeparamref name="T"/>,
/// false for an unsigned one whose <c>MinValue</c> is <c>0</c>) — a per-instantiation constant the
/// JIT folds, so the dead branch is eliminated in the specialized body. Subtraction always uses the
/// SIGNED accumulator: its intermediate can be negative even for an unsigned <typeparamref name="T"/>
/// (<c>u8: 5 -| 10</c>), and a signed clamp with <c>lo == T.MinValue == 0</c> saturates that to
/// <c>0</c> correctly — whereas a <c>UInt128</c> subtraction would wrap to a huge value and
/// mis-saturate to the max.
/// </para>
/// </remarks>
public static class ZigMath
{
    /// <summary>Capture the destination and its old value before evaluating a wrapping assignment's RHS.</summary>
    public static WrappingAssignment<T> Wrapping<T>(ref T target)
        where T : unmanaged, global::System.Numerics.IBinaryInteger<T>
        => new(ref target);

    public ref struct WrappingAssignment<T> where T : unmanaged, global::System.Numerics.IBinaryInteger<T>
    {
        private ref T _target;
        private readonly T _old;
        public WrappingAssignment(ref T target) { _target = ref target; _old = target; }
        public T Add(T value, int bits) => _target = NormalizeWrapping(unchecked(_old + value), bits);
        public T Sub(T value, int bits) => _target = NormalizeWrapping(unchecked(_old - value), bits);
        public T Mul(T value, int bits) => _target = NormalizeWrapping(unchecked(_old * value), bits);
    }

    private static T NormalizeWrapping<T>(T value, int bits)
        where T : unmanaged, global::System.Numerics.IBinaryInteger<T>
    {
        var carrierBits = Unsafe.SizeOf<T>() * 8;
        if (bits <= 0 || bits > carrierBits) throw new global::System.ArgumentOutOfRangeException(nameof(bits));
        var shift = carrierBits - bits;
        return (value << shift) >> shift;
    }

    /// <summary>Saturating add — <c>a +| b</c> clamped to <typeparamref name="T"/>'s range.</summary>
    public static T SatAdd<T>(T a, T b)
        where T : global::System.Numerics.IBinaryInteger<T>, global::System.Numerics.IMinMaxValue<T>
        => T.IsNegative(T.MinValue)
            ? ClampSigned<T>(global::System.Int128.CreateTruncating(a) + global::System.Int128.CreateTruncating(b))
            : ClampUnsigned<T>(global::System.UInt128.CreateTruncating(a) + global::System.UInt128.CreateTruncating(b));

    /// <summary>Saturating subtract — <c>a -| b</c> clamped to <typeparamref name="T"/>'s range.
    /// Always evaluated in the signed accumulator (the difference can be negative even for an
    /// unsigned <typeparamref name="T"/>, whose <c>MinValue</c> of <c>0</c> is then the floor).</summary>
    public static T SatSub<T>(T a, T b)
        where T : global::System.Numerics.IBinaryInteger<T>, global::System.Numerics.IMinMaxValue<T>
        => ClampSigned<T>(global::System.Int128.CreateTruncating(a) - global::System.Int128.CreateTruncating(b));

    /// <summary>Saturating multiply — <c>a *| b</c> clamped to <typeparamref name="T"/>'s range.</summary>
    public static T SatMul<T>(T a, T b)
        where T : global::System.Numerics.IBinaryInteger<T>, global::System.Numerics.IMinMaxValue<T>
        => T.IsNegative(T.MinValue)
            ? ClampSigned<T>(global::System.Int128.CreateTruncating(a) * global::System.Int128.CreateTruncating(b))
            : ClampUnsigned<T>(global::System.UInt128.CreateTruncating(a) * global::System.UInt128.CreateTruncating(b));

    // ---- Overflow-detecting arithmetic (road-to-zig-std B3) — @addWithOverflow & friends.
    // Each returns Zig's `struct { T, u1 }` as a C# `(T, byte)` ValueTuple: the WRAPPED result
    // (truncated to T, exactly like `+%`/`-%`/`*%`) plus a 0/1 overflow flag. Computed EXACTLY in a
    // 128-bit accumulator — every operand the lowering routes here is <= 64-bit (a 128-bit operand is
    // a loud cut, since detecting its overflow would need a still-wider accumulator) — then the flag
    // is set when truncating the exact result back to T changed the value. Signedness is the
    // per-instantiation constant `T.IsNegative(T.MinValue)` (the JIT folds the dead branch), and
    // subtraction always uses the signed accumulator (an unsigned difference can go negative, e.g.
    // `u8: 5 -% 10`) — mirroring the saturating helpers above.

    /// <summary><c>@addWithOverflow(a, b)</c> → <c>.{ a +% b, overflow }</c>.</summary>
    public static (T, byte) AddWithOverflow<T>(T a, T b)
        where T : global::System.Numerics.IBinaryInteger<T>, global::System.Numerics.IMinMaxValue<T>
        => T.IsNegative(T.MinValue)
            ? OverflowSigned<T>(global::System.Int128.CreateTruncating(a) + global::System.Int128.CreateTruncating(b))
            : OverflowUnsigned<T>(global::System.UInt128.CreateTruncating(a) + global::System.UInt128.CreateTruncating(b));

    /// <summary><c>@subWithOverflow(a, b)</c> → <c>.{ a -% b, overflow }</c>. Always the signed
    /// accumulator (the difference can be negative even for an unsigned <typeparamref name="T"/>).</summary>
    public static (T, byte) SubWithOverflow<T>(T a, T b)
        where T : global::System.Numerics.IBinaryInteger<T>, global::System.Numerics.IMinMaxValue<T>
        => OverflowSigned<T>(global::System.Int128.CreateTruncating(a) - global::System.Int128.CreateTruncating(b));

    /// <summary><c>@mulWithOverflow(a, b)</c> → <c>.{ a *% b, overflow }</c>.</summary>
    public static (T, byte) MulWithOverflow<T>(T a, T b)
        where T : global::System.Numerics.IBinaryInteger<T>, global::System.Numerics.IMinMaxValue<T>
        => T.IsNegative(T.MinValue)
            ? OverflowSigned<T>(global::System.Int128.CreateTruncating(a) * global::System.Int128.CreateTruncating(b))
            : OverflowUnsigned<T>(global::System.UInt128.CreateTruncating(a) * global::System.UInt128.CreateTruncating(b));

    // The 128-bit operands (a `u128` mantissa in std.fmt.parseFloat(f128, …), task #214) have no wider primitive
    // accumulator, so their exact result is a BigInteger. C# prefers these non-generic overloads for a UInt128 / Int128
    // pair, so the generic helpers above keep every narrower width.

    /// <summary><c>@addWithOverflow</c> over <c>u128</c>: the wrapped sum and whether the exact one leaves the range.</summary>
    public static (System.UInt128, byte) AddWithOverflow(System.UInt128 a, System.UInt128 b)
        => (unchecked(a + b), (System.Numerics.BigInteger)a + b > System.UInt128.MaxValue ? (byte)1 : (byte)0);

    /// <summary><c>@addWithOverflow</c> over <c>i128</c>.</summary>
    public static (System.Int128, byte) AddWithOverflow(System.Int128 a, System.Int128 b)
        => (unchecked(a + b), OutOfInt128((System.Numerics.BigInteger)a + b));

    /// <summary><c>@subWithOverflow</c> over <c>u128</c>: a difference below zero overflows.</summary>
    public static (System.UInt128, byte) SubWithOverflow(System.UInt128 a, System.UInt128 b)
        => (unchecked(a - b), a < b ? (byte)1 : (byte)0);

    /// <summary><c>@subWithOverflow</c> over <c>i128</c>.</summary>
    public static (System.Int128, byte) SubWithOverflow(System.Int128 a, System.Int128 b)
        => (unchecked(a - b), OutOfInt128((System.Numerics.BigInteger)a - b));

    /// <summary><c>@mulWithOverflow</c> over <c>u128</c>.</summary>
    public static (System.UInt128, byte) MulWithOverflow(System.UInt128 a, System.UInt128 b)
        => (unchecked(a * b), (System.Numerics.BigInteger)a * b > System.UInt128.MaxValue ? (byte)1 : (byte)0);

    /// <summary><c>@mulWithOverflow</c> over <c>i128</c>.</summary>
    public static (System.Int128, byte) MulWithOverflow(System.Int128 a, System.Int128 b)
        => (unchecked(a * b), OutOfInt128((System.Numerics.BigInteger)a * b));

    /// <summary><c>@shlWithOverflow</c> over <c>u128</c>: the shifted-out bits overflow.</summary>
    public static (System.UInt128, byte) ShlWithOverflow(System.UInt128 a, int shift)
        => (a << shift, ((System.Numerics.BigInteger)a << shift) > System.UInt128.MaxValue ? (byte)1 : (byte)0);

    /// <summary><c>@shlWithOverflow</c> over <c>i128</c>.</summary>
    public static (System.Int128, byte) ShlWithOverflow(System.Int128 a, int shift)
        => (a << shift, OutOfInt128((System.Numerics.BigInteger)a << shift));

    /// <summary>1 when an exact result leaves <c>i128</c>'s range, else 0.</summary>
    private static byte OutOfInt128(System.Numerics.BigInteger exact)
        => exact > System.Int128.MaxValue || exact < System.Int128.MinValue ? (byte)1 : (byte)0;

    /// <summary><c>@shlWithOverflow(a, shift)</c> → <c>.{ a &lt;&lt;% shift, overflow }</c>; the overflow
    /// bit is set when the shift loses any high bits (truncating the exact 128-bit shift changed the
    /// value). The shift amount is a small non-negative count (Zig's <c>Log2(T)</c>).</summary>
    public static (T, byte) ShlWithOverflow<T>(T a, int shift)
        where T : global::System.Numerics.IBinaryInteger<T>, global::System.Numerics.IMinMaxValue<T>
        => T.IsNegative(T.MinValue)
            ? OverflowSigned<T>(global::System.Int128.CreateTruncating(a) << shift)
            : OverflowUnsigned<T>(global::System.UInt128.CreateTruncating(a) << shift);

    /// <summary>Exact left shift within the source integer width, including non-carrier widths.
    /// Signed results must fit their signed range; unsigned results must lose no set bits.
    /// BigInteger supplies the wider accumulator for 128-bit operands, as in the overflow helpers.</summary>
    public static T ShlExact<T>(T value, System.Int128 shift, int bits)
        where T : global::System.Numerics.IBinaryInteger<T>, global::System.Numerics.IMinMaxValue<T>
    {
        var signed = T.IsNegative(T.MinValue);
        if (bits < 1 || bits > 128)
            throw new System.NotSupportedException("zig @shlExact supports scalar integer widths 1 through 128 only");
        if (shift < 0 || shift >= bits)
            throw new System.ArgumentOutOfRangeException(nameof(shift), "zig @shlExact shift amount must be non-negative and less than the integer bit width");
        var min = signed ? -(global::System.Numerics.BigInteger.One << (bits - 1)) : global::System.Numerics.BigInteger.Zero;
        var max = (global::System.Numerics.BigInteger.One << (bits - (signed ? 1 : 0))) - 1;
        if (min < global::System.Numerics.BigInteger.CreateChecked(T.MinValue)
            || max > global::System.Numerics.BigInteger.CreateChecked(T.MaxValue))
            throw new System.NotSupportedException("zig @shlExact logical width exceeds its managed integer carrier");
        var input = global::System.Numerics.BigInteger.CreateChecked(value);
        if (input < min || input > max)
            throw new System.OverflowException("zig @shlExact operand does not fit its logical integer width");
        var exact = input << (int)shift;
        if (exact < min || exact > max)
            throw new System.OverflowException("zig @shlExact overflow: shifted bits disagree with the result sign or leave the unsigned integer width");
        return T.CreateChecked(exact);
    }

    // ---- Zig math builtins (road-to-zig-std B3) — each maps to a BCL/generic-math primitive.
    // The Zig front-end coerces both operands to their peer integer type, so C# infers T and the
    // op runs at the right width. @min/@max/@rem/@divTrunc are ordinary; @mod/@divFloor differ from
    // C#'s truncating `%`/`/` for a negative divisor (they follow the DIVISOR's sign / round toward
    // negative infinity); @popCount counts set bits (width-agnostic — leading zero bits add nothing).

    /// <summary><c>@min(a, b)</c> — the lesser operand (Zig's variadic <c>@min</c>, V1 binary).</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static T Min<T>(T a, T b) where T : global::System.Numerics.IBinaryInteger<T> => a < b ? a : b;

    /// <summary><c>@max(a, b)</c> — the greater operand.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static T Max<T>(T a, T b) where T : global::System.Numerics.IBinaryInteger<T> => a > b ? a : b;

    /// <summary><c>@rem(a, b)</c> — truncated remainder (sign of the DIVIDEND) — identical to C#'s
    /// <c>%</c>, wrapped for a uniform builtin surface.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static T Rem<T>(T a, T b) where T : global::System.Numerics.IBinaryInteger<T> => a % b;

    /// <summary><c>@divTrunc(a, b)</c> — division rounding toward zero — identical to C#'s <c>/</c>.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static T DivTrunc<T>(T a, T b) where T : global::System.Numerics.IBinaryInteger<T> => a / b;

    /// <summary><c>@mod(a, b)</c> — floored modulo: the result takes the sign of the DIVISOR (unlike
    /// C#'s <c>%</c>, sign of the dividend). For an unsigned <typeparamref name="T"/> the two coincide.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static T Mod<T>(T a, T b) where T : global::System.Numerics.IBinaryInteger<T>
    {
        var r = a % b;
        return !T.IsZero(r) && (T.IsNegative(r) != T.IsNegative(b)) ? r + b : r;
    }

    /// <summary><c>@mod(a, b)</c> of floats: the floored remainder, taking the sign of the divisor (zig allows no
    /// <c>%</c> on a runtime float, so this is how a float remainder is spelled).</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static double Mod(double a, double b)
    {
        var r = a % b;
        return r != 0 && (r < 0) != (b < 0) ? r + b : r;
    }

    /// <summary><c>@mod(a, b)</c> of <c>f32</c> floats (see the <c>double</c> overload).</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static float Mod(float a, float b)
    {
        var r = a % b;
        return r != 0 && (r < 0) != (b < 0) ? r + b : r;
    }

    /// <summary><c>@rem(a, b)</c> of floats: the truncated remainder (sign of the dividend), C#'s <c>%</c>.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static double Rem(double a, double b) => a % b;

    /// <summary><c>@rem(a, b)</c> of <c>f32</c> floats.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static float Rem(float a, float b) => a % b;

    /// <summary><c>@rem(a, b)</c> of <c>f128</c> floats (task #214): the truncated remainder, C's <c>fmodl</c>.</summary>
    public static Float128 Rem(Float128 a, Float128 b) => Float128.Fmod(a, b);

    /// <summary><c>@mod(a, b)</c> of <c>f128</c> floats: the floored remainder, taking the sign of the divisor.</summary>
    public static Float128 Mod(Float128 a, Float128 b)
    {
        var r = Float128.Fmod(a, b);
        return !Float128.IsZero(r) && Float128.IsNegative(r) != Float128.IsNegative(b) ? r + b : r;
    }

    /// <summary><c>@min(a, b)</c> of <c>f128</c> floats: a NaN operand yields the other one, as zig's does.</summary>
    public static Float128 Min(Float128 a, Float128 b)
        => Float128.IsNaN(a) ? b : Float128.IsNaN(b) ? a : a < b ? a : b;

    /// <summary><c>@max(a, b)</c> of <c>f128</c> floats: a NaN operand yields the other one, as zig's does.</summary>
    public static Float128 Max(Float128 a, Float128 b)
        => Float128.IsNaN(a) ? b : Float128.IsNaN(b) ? a : a > b ? a : b;

    /// <summary><c>@divFloor(a, b)</c> — division rounding toward negative infinity (unlike C#'s <c>/</c>,
    /// toward zero). For non-negative operands the two coincide.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static T DivFloor<T>(T a, T b) where T : global::System.Numerics.IBinaryInteger<T>
    {
        var q = a / b;
        var r = a % b;
        return !T.IsZero(r) && (T.IsNegative(r) != T.IsNegative(b)) ? q - T.One : q;
    }

    /// <summary>Integer division rounded toward positive infinity. The optional bit width is
    /// Zig's logical width when its C# carrier is wider. Invalid operands throw rather than wrap;
    /// this helper does not model Zig's build-mode-dependent panic machinery.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static T DivCeil<T>(T a, T b, int bitWidth = 0)
        where T : global::System.Numerics.IBinaryInteger<T>, global::System.Numerics.IMinMaxValue<T>
    {
        var storageBits = int.CreateChecked(T.PopCount(T.AllBitsSet));
        if (bitWidth < 0 || bitWidth > storageBits)
            throw new global::System.ArgumentOutOfRangeException(nameof(bitWidth));
        if (T.IsZero(b)) throw new global::System.DivideByZeroException();
        if (T.IsNegative(T.MinValue) && b == -T.One)
        {
            var minimum = bitWidth == 0 || bitWidth == storageBits ? T.MinValue : -(T.One << (bitWidth - 1));
            if (a == minimum) throw new global::System.OverflowException("zig @divCeil integer overflow");
        }
        var quotient = a / b;
        var remainder = a % b;
        return !T.IsZero(remainder) && T.IsNegative(remainder) == T.IsNegative(b)
